  function objectiveFormatTime(seconds){
    seconds = Math.max(0, Math.ceil(Number(seconds) || 0));
    const m = Math.floor(seconds / 60), s = seconds % 60;
    return m > 0 ? (m + ':' + String(s).padStart(2,'0')) : (s + 's');
  }
  function renderObjectivePanel(){
    const panel = document.getElementById('tempObjectivePanel');
    const resultsOpen = document.body && document.body.getAttribute('data-results-open') === '1';
    if (!panel || !state || state.inMenu || !state.running || isSandboxMode() || resultsOpen || (state.wave || 1) < TEMP_OBJECTIVE_START_WAVE) { if(panel) panel.classList.remove('visible'); return; }
    const owner = localObjectiveOwner();
    const obj = owner && owner.objectives;
    const pending = obj && obj.pending;
    const active = obj && obj.active;
    const title = document.getElementById('tempObjectiveTitle');
    const rewardEl = document.getElementById('tempObjectiveReward');
    const desc = document.getElementById('tempObjectiveDesc');
    const meta = document.getElementById('tempObjectiveMeta');
    const metaLabel = document.getElementById('tempObjectiveMetaLabel');
    const timeEl = document.getElementById('tempObjectiveTime');
    const metaProgress = document.getElementById('tempObjectiveMetaProgress');
    const prog = document.getElementById('tempObjectiveProgress');
    const actions = document.getElementById('tempObjectiveActions');
    panel.classList.add('visible');
    panel.classList.toggle('pending', !!pending);
    panel.classList.toggle('active', !!active);
    panel.classList.toggle('idle', !pending && !active);
    panel.setAttribute('aria-hidden','false');
    const cur = pending || active;
    if (cur && obj && obj.flash && obj.flash.seq !== panel._objectiveFlashSeq){
      panel._objectiveFlashSeq = obj.flash.seq;
      panel.classList.remove('complete','failed');
      void panel.offsetWidth;
      if (obj.flash.type === 'complete') panel.classList.add('complete');
      if (obj.flash.type === 'failed') panel.classList.add('failed');
      setTimeout(function(){ try{ panel.classList.remove('complete','failed'); }catch(_){} }, 760);
    }
    if (!cur){
      const dots = '.'.repeat(1 + (Math.floor(performance.now() / 420) % 3));
      if (title){ title.textContent = ''; title.style.display = ''; }
      if (rewardEl){ rewardEl.textContent = ''; rewardEl.classList.remove('visible'); }
      if (desc) desc.textContent = 'Aguardando próximo objetivo' + dots;
      if (meta) meta.style.display = 'none';
      if (metaLabel) metaLabel.textContent = '';
      if (timeEl) timeEl.textContent = '';
      if (metaProgress) metaProgress.textContent = '';
      if (prog) prog.style.width = '0%';
      if (actions) actions.style.display = 'none';
      return;
    }
    if (title) title.style.display = '';
    if (title) title.textContent = cur.title || 'Objetivo';
    if (rewardEl){
      rewardEl.textContent = '+' + (cur.reward || 0) + ' pts';
      rewardEl.classList.add('visible');
    }
    if (desc) desc.textContent = cur.desc || '';
    if (actions) actions.style.display = pending ? 'flex' : 'none';
    if (meta) meta.style.display = 'flex';
    let pct = 0, labelText = '', timeText = '', progressText = '';
    if (pending){
      const left = Math.max(0, Number(pending.remaining == null ? TEMP_OBJECTIVE_OFFER_SECONDS : pending.remaining));
      pct = 100 * (left / Math.max(1, Number(pending.offerDuration) || TEMP_OBJECTIVE_OFFER_SECONDS));
    } else if (active){
      const left = objectiveTimeLeft(active);
      const target = Math.max(1, Number(active.target || active.duration || 1));
      pct = Math.max(0, Math.min(100, ((active.progress || 0) / target) * 100));
      if (active.kind === 'timer' || active.kind === 'survive') pct = Math.max(pct, Math.min(100, objectiveElapsedSeconds(active) / Math.max(1, active.duration || target) * 100));
      if (active.kind !== 'timer' && active.kind !== 'survive') timeText = objectiveFormatTime(left);
      progressText = Math.min(target, Math.floor(active.progress || 0)) + '/' + target;
    }
    if (metaLabel) metaLabel.textContent = labelText;
    if (timeEl) timeEl.textContent = timeText;
    if (metaProgress) metaProgress.textContent = progressText;
    if (meta) meta.style.display = pending ? 'none' : 'flex';
    if (prog) prog.style.width = pct.toFixed(1) + '%';
  }
  (function bindTemporaryObjectiveButtons(){
    const a = document.getElementById('tempObjectiveAcceptBtn');
    const d = document.getElementById('tempObjectiveDeclineBtn');
    if (a && !a._boundTempObjective){ a._boundTempObjective = true; a.addEventListener('click', objectiveAccept); }
    if (d && !d._boundTempObjective){ d._boundTempObjective = true; d.addEventListener('click', objectiveDecline); }
  })();

  function isLocalLineDefenseObjectiveActive(){
    const owner = localObjectiveOwner();
    const obj = owner && owner.objectives;
    const active = obj && obj.active;
    return !!(active && active.id === 'line_defense');
  }
  function drawLineDefenseObjectiveRange(ctx){
    if (!state || !state.gold || !isLocalLineDefenseObjectiveActive()) return;
    const rangeTiles = 2;
    const size = (rangeTiles * 2 + 1) * TILE;
    const ax = (state.gold.x - rangeTiles) * TILE;
    const ay = (state.gold.y - rangeTiles) * TILE;
    const cx = state.gold.x * TILE + TILE / 2;
    const cy = state.gold.y * TILE + TILE / 2;
    const pulse = 0.5 + 0.5 * Math.sin((state.t || 0) * 5.2);
    ctx.save();
    ctx.globalAlpha = 0.08 + pulse * 0.05;
    const grad = ctx.createRadialGradient(cx, cy, 2, cx, cy, size * 0.72);
    grad.addColorStop(0, '#ff3b3b');
    grad.addColorStop(1, 'rgba(255,59,59,0)');
    ctx.fillStyle = grad;
    ctx.fillRect(ax, ay, size, size);
    ctx.globalAlpha = 0.48 + pulse * 0.28;
    ctx.strokeStyle = pulse > 0.5 ? '#ff6b6b' : '#d92b2b';
    ctx.lineWidth = 1.5;
    ctx.setLineDash([4,3]);
    ctx.strokeRect(ax + 1, ay + 1, size - 2, size - 2);
    ctx.setLineDash([]);
    ctx.restore();
  }

  function tryMove2(key){
    if (!state.coop || !state.player2) return;
    // Prevent movement when player2 is down
    if (state.player2.hp <= 0) return;
    const origPlayer = state.player;
    const origKeys = state.keysHeld;
    state.player = state.player2;
    state.keysHeld = state.keysHeld2;
    // Map arrow keys to WASD letters expected by tryMove()
    let mk = null;
    if (key === "ArrowUp") mk = "w";
    else if (key === "ArrowDown") mk = "s";
    else if (key === "ArrowLeft") mk = "a";
    else if (key === "ArrowRight") mk = "d";
    else mk = key;
    tryMove(mk);
    state.player = origPlayer;
    state.keysHeld = origKeys;
  }

  function tryShoot2(){
    if (!state.coop || !state.player2) return;
    // Prevent shooting when player2 is down
    if (state.player2.hp <= 0) return;
    const origPlayer = state.player;
    const origLast = state.lastShotAt;
    const bulletsBefore = state.bullets.length;
    state.player = state.player2;
    // Use player2's own last shot timestamp
    state.lastShotAt = (state.lastShotAt2||-9999);
    // Override bullet stats and cooldown for player2
    const origCd   = state.shotCooldownMs;
    const origSpd  = state.bulletSpeed;
    const origPr   = state.bulletPierce;
    const origBnc  = state.bulletBounce;
    state.shotCooldownMs = (typeof state.shotCooldownMs2 === 'number') ? state.shotCooldownMs2 : state.shotCooldownMs;
    state.bulletSpeed   = (typeof state.bulletSpeed2 === 'number') ? state.bulletSpeed2 : state.bulletSpeed;
    state.bulletPierce  = (typeof state.bulletPierce2 === 'number') ? state.bulletPierce2 : state.bulletPierce;
    state.bulletBounce  = (typeof state.bulletBounce2 === 'number') ? state.bulletBounce2 : state.bulletBounce;
    tryShoot();
    // Capture updated timestamp and restore stats
    state.lastShotAt2 = state.lastShotAt;
    state.shotCooldownMs = origCd;
    state.bulletSpeed   = origSpd;
    state.bulletPierce  = origPr;
    state.bulletBounce  = origBnc;
    state.lastShotAt = origLast;
    state.player = origPlayer;
    // mark bullets created by player2
    for (let i=bulletsBefore; i<state.bullets.length; i++){
      const bb = state.bullets[i];
      if (bb && bb.src === 'player'){
        bb.src = 'player2';
      }
    }
  }

  function getOnlinePlayersSorted(){
    const list = (state && state.onlinePlayers) ? state.onlinePlayers.slice() : [];
    return list.sort((a,b)=>((a.slot||0)-(b.slot||0)));
  }

  function getOnlineActorByClient(id){
    if (!state || !state.onlinePlayers) return null;
    for (const p of state.onlinePlayers){
      if (p && p.id === id) return p.actor || null;
    }
    return null;
  }

  function getOnlinePlayerByActor(actor){
    if (!state || !state.onlinePlayers || !actor) return null;
    for (const p of state.onlinePlayers){
      if (p && p.actor === actor) return p;
    }
    return null;
  }

  function cowboyOccupiesTile(tx, ty, exceptActor){
    if (!state) return false;
    if (state.onlineCoop) return false;
    if (state.coop){
      const p1 = state.player1 || state.player;
      const p2 = state.player2;
      if (p1 && p1 !== exceptActor && p1.hp > 0 && p1.x === tx && p1.y === ty) return true;
      if (p2 && p2 !== exceptActor && p2.hp > 0 && p2.x === tx && p2.y === ty) return true;
    }
    return false;
  }

  function bulletBelongsToOnlinePlayer(b, op){
    if (!b || !op) return false;
    if (b.ownerId && op.id === b.ownerId) return true;
    if (typeof b.src === 'string' && b.src === ('online:' + op.id)) return true;
    if (b.src === 'player' && (op.slot|0) === 1) return true;
    if (b.src === 'player2' && (op.slot|0) === 2) return true;
    return false;
  }

  function bulletBelongsToLocalCoopActor(b, actor){
    if (!b || !actor) return false;
    if (actor === state.player2) return b.src === 'player2';
    if (actor === state.player1 || actor === state.player) return b.src === 'player';
    return false;
  }

  function bulletBlockedByCowboy(b, bulletHitsTile){
    if (!b || !bulletHitsTile) return false;
    if (state && state.onlineCoop) return false;
    const playerBullet = b.src === 'player' || b.src === 'player2' || (typeof b.src === 'string' && b.src.indexOf('online:') === 0);
    if (!playerBullet) return false;
    if (state && state.onlineCoop && Array.isArray(state.onlinePlayers)){
      for (const op of state.onlinePlayers){
        if (!op || op.connected === false || !op.actor || op.actor.hp <= 0) continue;
        if (bulletBelongsToOnlinePlayer(b, op)) continue;
        if (bulletHitsTile(op.actor.x, op.actor.y)) return true;
      }
      return false;
    }
    if (state && state.coop){
      const actors = [];
      if (state.player1 || state.player) actors.push(state.player1 || state.player);
      if (state.player2) actors.push(state.player2);
      for (const actor of actors){
        if (!actor || actor.hp <= 0 || bulletBelongsToLocalCoopActor(b, actor)) continue;
        if (bulletHitsTile(actor.x, actor.y)) return true;
      }
    }
    return false;
  }

  function isLocalOnlineActor(actor){
    if (!state || !state.onlineCoop) return true;
    const p = getOnlinePlayerByActor(actor);
    return !!(p && p.id === state.onlineClientId);
  }

  function getAliveCowboys(){
    const list = [];
    if (!state) return list;
    if (state.onlineCoop && state.onlinePlayers){
      for (const p of state.onlinePlayers){
        if (!p || p.connected === false || !p.actor || p.actor.hp <= 0) continue;
        list.push(p.actor);
      }
      return list;
    }
    if (state.player && state.player.hp > 0) list.push(state.player);
    if (state.coop && state.player2 && state.player2.hp > 0) list.push(state.player2);
    return list;
  }

  function nearestAliveCowboyFrom(entity){
    if (!entity) return null;
    const cowboys = getAliveCowboys();
    let best = null;
    let bestDist = Infinity;
    for (const actor of cowboys){
      const dist = Math.abs(entity.x - actor.x) + Math.abs(entity.y - actor.y);
      if (dist < bestDist){
        bestDist = dist;
        best = actor;
      }
    }
    return best ? { actor:best, dist:bestDist } : null;
  }

  function allOnlineCowboysDown(){
    if (!state || !state.onlineCoop || !state.onlinePlayers) return false;
    const connected = state.onlinePlayers.filter(function(p){ return p && p.connected !== false; });
    return connected.length > 0 && connected.every(function(p){ return !p.actor || p.actor.hp <= 0; });
  }

  function applyEnemyDamageToCowboy(actor, dmg, srcX, srcY, invulMs){
    if (!actor || actor.hp <= 0) return false;
    if (triggerSandboxCowboyImmortalBlock(actor)) return false;
    if ((actor.invulT || 0) > 0 || (actor === state.player && (state.playerInvulT || 0) > 0)) return false;
    const damagedOnlinePlayer = getOnlinePlayerByActor(actor);
    actor.hp = Math.max(0, actor.hp - dmg);
    if (actor.hp > 0) actor._enemyDownNotified = false;
    if (!state.onlineCoop || isLocalOnlineActor(actor)){
      state.playerFlashT = 0.5;
      state.playerWarnT = 1.0;
    }
    if (invulMs) actor.invulT = Math.max(actor.invulT || 0, invulMs);
    if (actor === state.player && invulMs) state.playerInvulT = invulMs;
    state.shakeT = Math.min(0.55, (state.shakeT||0) + 0.30);
    state.shakeMag = Math.max(3.0, state.shakeMag||0);
    beep(140,0.05,'triangle',0.035);
    emitOnlineAudioEvent('cowboy-hit', { x:actor.x, y:actor.y, targetId:damagedOnlinePlayer && damagedOnlinePlayer.id || null, shakeT:0.30, shakeMag:3.0 });
    if (typeof srcX === 'number' && typeof srcY === 'number') spawnAssassinHitFX(srcX, srcY);
    spawnPlayerHitFX(actor.x, actor.y);
    if (state.onlineCoop && allOnlineCowboysDown()){
      state.running = false;
      state.gameOverReason = "player";
      musicStop();
      try{ window._expSystem&&window._expSystem.onGameOver(state,'player'); }catch(_){}
    } else if (actor.hp <= 0){
      if (!state.onlineCoop){
        if (actor === state.player) state.dead1 = true;
        if (actor === state.player2) state.dead2 = true;
      }
      if (!actor._enemyDownNotified){
        actor._enemyDownNotified = true;
        try{ pushSyncedPopup("COWBOY ABATIDO!", "#ff4d4d", actor.x*TILE + TILE/2, actor.y*TILE + 10); }catch(_){}
        try{ noise(0.08, 0.05); beep(90, 0.08, "square", 0.03); }catch(_){}
        emitOnlineAudioEvent('enemy-death', { kind:'heavy' });
      }
      if (!state.onlineCoop && actor === state.player){
        state.running = false;
        state.gameOverReason = "player";
        musicStop();
        try{ window._expSystem&&window._expSystem.onGameOver(state,'player'); }catch(_){}
      }
    }
    return true;
  }

  function makeOnlineActor(slot, gx, gy){
    const spots = {
      1: { x:gx, y:gy+2, face:DIRS.up },
      2: { x:gx, y:gy-2, face:DIRS.down },
      3: { x:gx-2, y:gy, face:DIRS.right },
      4: { x:gx+2, y:gy, face:DIRS.left }
    };
    const s = spots[slot] || spots[1];
    return { x:s.x, y:s.y, face:s.face, moveLock:false, moveLockMs:220, nextMoveAt:0, hp:100, max:100 };
  }

  function defaultOnlineUpgrades(){
    return {
      shotCooldownMs: 750,
      bulletSpeed: Math.round(11 * TILE),
      bulletPierce: 0,
      bulletBounce: 0,
      bulletSpdLevel: 0,
      explosiveLevel: 0,
      aimLevel: 0,
      rollLevel: 0,
      rollCooldownMs: 2000,
      rollCost: 800,
      lastRollAt: -9999,
      moveSpdCount: 0,
      saraivadaLevel: 0,
      lastSaraivadaAt: -99999,
      balaTranslucida: false
    };
  }

  function syncOnlineScoreAliases(){
    if (!state || !state.onlinePlayers) return;
    for (const p of state.onlinePlayers){
      const slot = p && (p.slot|0);
      if (!slot) continue;
      state['score' + slot] = p.score || 0;
      state['totalScore' + slot] = p.totalScore || 0;
    }
  }

  function getActiveShopScore(){
    if (state.onlineCoop){
      const p = onlinePlayerBySlot(state.activeShopPlayer || 1);
      return p ? (p.score || 0) : 0;
    }
    if (state.coop) return state.activeShopPlayer === 1 ? (state.score1 || 0) : (state.score2 || 0);
    return state.score || 0;
  }

  function setActiveShopScore(v){
    v = Math.max(0, Math.floor(Number(v) || 0));
    if (state.onlineCoop){
      const p = onlinePlayerBySlot(state.activeShopPlayer || 1);
      if (p) p.score = v;
      syncOnlineScoreAliases();
      return;
    }
    if (state.coop){
      if (state.activeShopPlayer === 1) state.score1 = v;
      else state.score2 = v;
    } else {
      state.score = v;
    }
  }

  function refundActiveShopCost(cost){
    setActiveShopScore(getActiveShopScore() + (Number(cost) || 0));
  }

  function onlineActiveUpgradeContext(){
    if (!state || !state.onlineCoop) return null;
    const p = onlinePlayerBySlot(state.activeShopPlayer || 1);
    if (!p) return null;
    p.upgrades = Object.assign(defaultOnlineUpgrades(), p.upgrades || {});
    return { player:p, upgrades:p.upgrades, actor:p.actor || null };
  }

  function getOnlineSharedUpgradeState(){
    return {
      allyLevel: state.allyLevel || 0,
      allyFireMs: state.allyFireMs || 900,
      partnerIrVision: !!state.partnerIrVision,
      dogLevel: state.dogLevel || 0,
      dogWildInstinct: !!state.dogWildInstinct,
      dynaLevel: state.dynaLevel == null ? -1 : state.dynaLevel,
      xerifeLevel: state.xerifeLevel || 0,
      xerifePerpetualPrison: !!state.xerifePerpetualPrison,
      xerifeDoubleLasso: !!state.xerifeDoubleLasso,
      dinamiteiroLevel: state.dinamiteiroLevel || 0,
      dinamiteiroShortFuse: !!state.dinamiteiroShortFuse,
      reparadorLevel: state.reparadorLevel || 0,
      reparadorInstantUnlocked: !!state.reparadorInstantUnlocked
    };
  }

  function applyOnlineSharedUpgradeState(shared){
    if (!state || !shared) return;
    state.allyLevel = Math.max(0, shared.allyLevel|0);
    state.allyFireMs = Math.max(300, Number(shared.allyFireMs) || 900);
    state.partnerIrVision = !!shared.partnerIrVision;
    state.dogLevel = Math.max(0, shared.dogLevel|0);
    state.dogWildInstinct = !!shared.dogWildInstinct;
    if (shared.dynaLevel != null) state.dynaLevel = Math.max(-1, Math.min(4, shared.dynaLevel|0));
    state.xerifeLevel = Math.max(0, shared.xerifeLevel|0);
    state.xerifePerpetualPrison = !!shared.xerifePerpetualPrison;
    state.xerifeDoubleLasso = !!shared.xerifeDoubleLasso;
    state.dinamiteiroLevel = Math.max(0, Math.min(3, shared.dinamiteiroLevel|0));
    state.dinamiteiroShortFuse = !!shared.dinamiteiroShortFuse;
    state.reparadorLevel = Math.max(0, shared.reparadorLevel|0);
    state.reparadorInstantUnlocked = !!shared.reparadorInstantUnlocked;
    try{ const p = getPartner(); if (p) p.level = Math.max(1, state.allyLevel || p.level || 1); }catch(_){}
    try{ const d = getDog(); if (d){ d.level = Math.max(1, state.dogLevel || d.level || 1); d.wildInstinct = !!state.dogWildInstinct; d.sniffDur = state.dogWildInstinct ? 0 : dogSniffDurationForLevel(d.level); } }catch(_){}
    try{ const x = getXerife(); if (x) x.level = Math.max(1, state.xerifeLevel || x.level || 1); }catch(_){}
    try{ const dm = getDinamiteiro(); if (dm) dm.level = Math.max(1, state.dinamiteiroLevel || dm.level || 1); }catch(_){}
    try{ const r = getReparador(); if (r) r.level = Math.max(1, state.reparadorLevel || r.level || 1); }catch(_){}
    try{ if (window._refreshDogMenu) window._refreshDogMenu(); }catch(_){}
    try{ if (window._refreshXerifeMenu) window._refreshXerifeMenu(); }catch(_){}
    try{ if (window._refreshDinamiteiroMenu) window._refreshDinamiteiroMenu(); }catch(_){}
    try{ if (window._refreshReparadorMenu) window._refreshReparadorMenu(); }catch(_){}
    try{ if (window._refreshPartnerMenu) window._refreshPartnerMenu(); }catch(_){}
  }

  function getOnlineMapMenuPayer(){
    if (!state || !state.onlineCoop) return null;
    return onlinePlayerById(state._onlineMapMenuPayerId) || onlineLocalPlayer();
  }

  function getMapMenuScore(){
    if (state.onlineCoop){
      const p = getOnlineMapMenuPayer();
      return p ? (p.score || 0) : 0;
    }
    if (state.coop) return state.activeShopPlayer === 1 ? (state.score1 || 0) : (state.score2 || 0);
    return state.score || 0;
  }

  function setMapMenuScore(v){
    v = Math.max(0, Math.floor(Number(v) || 0));
    if (state.onlineCoop){
      const p = getOnlineMapMenuPayer();
      if (p) p.score = v;
      syncOnlineScoreAliases();
      return;
    }
    if (state.coop){
      if (state.activeShopPlayer === 1) state.score1 = v;
      else state.score2 = v;
    } else {
      state.score = v;
    }
  }

  function sendOnlineMapMenuAction(op){
    if (!state || !state.onlineCoop || !op) return false;
    if (state.onlineRole === 'client'){
      return onlineSendAction({type:'ally-menu', op:op});
    }
    return false;
  }

  function applyGoldHealFromMapMenu(){
    if (!state || !state.gold) return { ok:false, err:'state' };
    const cost = 200;
    const before = state.gold.hp | 0;
    const max = state.gold.max | 0;
    if (before >= max) return { ok:false, err:'full' };
    if (getMapMenuScore() < cost) return { ok:false, err:'nomoney' };
    setMapMenuScore(getMapMenuScore() - cost);
    state.gold.hp = Math.min(max, before + 20);
    const gained = (state.gold.hp | 0) - before;
    if (gained <= 0){
      setMapMenuScore(getMapMenuScore() + cost);
      return { ok:false, err:'full' };
    }
    playGoldHealMenuFeedback(gained);
    try{
      const _gInfo=document.getElementById('goldMenuInfo');
      if(_gInfo) _gInfo.textContent='HP: '+(state.gold.hp|0)+'/'+state.gold.max;
      const _ghBtn=document.getElementById('goldMenuHealBtn');
      if(_ghBtn) _ghBtn.disabled=(state.gold.hp>=state.gold.max);
    }catch(_){}
    try{ updateHUD(); }catch(_){}
    return { ok:true, gained:gained };
  }

  function requestGoldHealFromMapMenu(){
    if (!state || !state.gold) return;
    if ((state.gold.hp|0) >= (state.gold.max|0)){
      try{ (window._profSkinToast||window.__profSkinToast||null)?.("A vida do ouro está cheia!", true); }catch(_){ try{ toastMsg("A vida do ouro está cheia!"); }catch(__){} }
      try{ beep(180,0.09,'sawtooth',0.07); }catch(_){}
      return;
    }
    if (getMapMenuScore() < 200){
      try{ (window._profSkinToast||window.__profSkinToast||null)?.("Pontuação insuficiente", true); }catch(_){ try{ toastMsg("Pontuação insuficiente"); }catch(__){} }
      try{ beep(180,0.09,'sawtooth',0.07); }catch(_){}
      return;
    }
    if (state.onlineCoop && state.onlineRole === 'client'){
      if (sendOnlineMapMenuAction('gold-heal')){
        try{ (window._profSndBuy||window.__profSndBuy||null)?.(); }catch(_){}
        try{ (window._profSkinToast||window.__profSkinToast||null)?.("+20 vida do ouro!", false); }catch(_){}
      }
      return;
    }
    const r = applyGoldHealFromMapMenu();
    if (r && r.ok){
      try{ (window._profSndBuy||window.__profSndBuy||null)?.(); }catch(_){}
      try{ (window._profSkinToast||window.__profSkinToast||null)?.("+20 vida do ouro!", false); }catch(_){}
      if (state.onlineCoop && state.onlineRole === 'host'){
        try{ emitOnlineAudioEvent('gold-heal', { gained:r.gained || 20 }); }catch(_){}
        try{ forceOnlineMetaSnapshotSoon(); }catch(_){}
      }
    }
  }

  (function(){
    const btn = document.getElementById('goldMenuHealBtn');
    if (btn && !btn._boundGoldHeal){
      btn._boundGoldHeal = true;
      btn.addEventListener('click', function(ev){
        ev.preventDefault();
        ev.stopPropagation();
        requestGoldHealFromMapMenu();
      });
    }
  })();

  function handleOnlineAllyMenuAction(clientId, action){
    if (!state || state.onlineRole !== 'host' || !clientId || !action) return;
    const payer = onlinePlayerById(clientId);
    if (!payer) return;
    const prevPayer = state._onlineMapMenuPayerId;
    state._onlineMapMenuPayerId = clientId;
    try{
      if (action.op === 'partner-upgrade'){
        const next = window._G && window._G.getNextAllyUpgradeCost ? window._G.getNextAllyUpgradeCost() : null;
        if (next == null || getMapMenuScore() < next) return;
        setMapMenuScore(getMapMenuScore() - next);
        const r = applyAllyUpgradeCore();
        if (r && r.err === 'max') setMapMenuScore(getMapMenuScore() + next);
      } else if (action.op === 'partner-ir'){
        if (state.partnerIrVision || getMapMenuScore() < PARTNER_IR_VISION_COST) return;
        setMapMenuScore(getMapMenuScore() - PARTNER_IR_VISION_COST);
        state.partnerIrVision = true;
        const pr = getPartner();
        try{ playPartnerIrVisionPurchaseSfx(); }catch(_){}
        try{ if (pr) spawnPartnerIrVisionPurchaseFX(pr.x, pr.y); }catch(_){}
        try{ if (pr) emitOnlineAudioEvent('partner-ir', { x:pr.x, y:pr.y, sourceId:clientId }); }catch(_){}
      } else if (action.op === 'reparador-upgrade'){
        applyReparadorUpgradeFromMapMenu();
      } else if (action.op === 'reparador-instant'){
        const r = applyReparadorInstantUnlockFromMapMenu();
        if (r && r.ok){
          const rep = getReparador();
          try{ playAllyAbilityPurchaseShake(); }catch(_){}
          try{ if (rep) emitOnlineAudioEvent('reparador-instant-unlock', { x:rep.x, y:rep.y, sourceId:clientId }); }catch(_){}
        }
      } else if (action.op === 'dog-upgrade'){
        applyDogUpgradeFromMapMenu();
      } else if (action.op === 'dog-wild'){
        const r = applyDogWildInstinctFromMapMenu();
        if (r && r.ok){
          const d = getDog();
          try{ if (d) emitOnlineAudioEvent('dog-wild-instinct', { x:d.x, y:d.y, sourceId:clientId }); }catch(_){}
        }
      } else if (action.op === 'xerife-upgrade'){
        applyXerifeUpgradeFromMapMenu();
      } else if (action.op === 'xerife-prison'){
        const r = applyXerifePerpetualPrisonFromMapMenu();
        if (r && r.ok){
          const x = getXerife();
          try{ if (x) emitOnlineAudioEvent('xerife-prison', { x:x.x, y:x.y, sourceId:clientId }); }catch(_){}
        }
      } else if (action.op === 'xerife-double-lasso'){
        const r = applyXerifeDoubleLassoFromMapMenu();
        if (r && r.ok){
          const x = getXerife();
          try{ if (x) emitOnlineAudioEvent('xerife-double-lasso', { x:x.x, y:x.y, sourceId:clientId }); }catch(_){}
        }
      } else if (action.op === 'dinamiteiro-upgrade'){
        applyDinamiteiroUpgradeFromMapMenu();
      } else if (action.op === 'dinamiteiro-short-fuse'){
        const r = applyDinamiteiroShortFuseFromMapMenu();
        if (r && r.ok){
          const d = getDinamiteiro();
          try{ if (d) emitOnlineAudioEvent('dinamiteiro-short-fuse', { x:d.x, y:d.y, sourceId:clientId }); }catch(_){}
        }
      } else if (action.op === 'gold-heal'){
        const r = applyGoldHealFromMapMenu();
        if (r && r.ok){
          try{ emitOnlineAudioEvent('gold-heal', { gained:r.gained || 20 }); }catch(_){}
        }
      }
      try{ refreshShopVisibility(); }catch(_){}
      try{ if (window._refreshPartnerMenu) window._refreshPartnerMenu(); }catch(_){}
      try{ if (window._refreshDogMenu) window._refreshDogMenu(); }catch(_){}
      try{ if (window._refreshXerifeMenu) window._refreshXerifeMenu(); }catch(_){}
      try{ if (window._refreshDinamiteiroMenu) window._refreshDinamiteiroMenu(); }catch(_){}
      try{ if (window._refreshReparadorMenu) window._refreshReparadorMenu(); }catch(_){}
      try{ updateHUD(); }catch(_){}
      try{ forceOnlineMetaSnapshotSoon(); }catch(_){}
    }finally{
      state._onlineMapMenuPayerId = prevPayer || null;
    }
  }

  function loadOnlineShopContext(p){
    if (!state || !state.onlineCoop || !p) return;
    const up = Object.assign(defaultOnlineUpgrades(), p.upgrades || {});
    p.upgrades = up;
    state.shotCooldownMs = up.shotCooldownMs;
    state.bulletSpeed = up.bulletSpeed;
    state.bulletPierce = up.bulletPierce;
    state.bulletBounce = up.bulletBounce;
    state.bulletSpdLevel = up.bulletSpdLevel;
    state.explosiveLevel = up.explosiveLevel;
    state.aimLevel = up.aimLevel;
    state.rollLevel = up.rollLevel;
    state.rollCooldownMs = activeRollCooldownMs(up.rollLevel, up.rollCooldownMs);
    state.rollCost1 = up.rollCost;
    state.rollCost2 = up.rollCost;
    state.lastRollAt = up.lastRollAt;
    state.saraivadaLevel = up.saraivadaLevel;
    state.lastSaraivadaAt = up.lastSaraivadaAt;
    state.balaTranslucida = !!up.balaTranslucida;
    if (p.actor) p.actor.moveSpdCount = up.moveSpdCount || 0;
    syncOnlineScoreAliases();
  }

  function saveOnlineShopContext(p){
    if (!state || !state.onlineCoop || !p) return;
    const up = Object.assign(defaultOnlineUpgrades(), p.upgrades || {});
    up.shotCooldownMs = state.shotCooldownMs;
    up.bulletSpeed = state.bulletSpeed;
    up.bulletPierce = state.bulletPierce || 0;
    up.bulletBounce = state.bulletBounce || 0;
    up.bulletSpdLevel = state.bulletSpdLevel || 0;
    up.explosiveLevel = state.explosiveLevel || 0;
    up.aimLevel = state.aimLevel || 0;
    up.rollLevel = state.rollLevel || 0;
    up.rollCooldownMs = activeRollCooldownMs(up.rollLevel || 0, state.rollCooldownMs || 2000);
    up.rollCost = state.rollCost1 || state.rollCost2 || up.rollCost || 800;
    up.lastRollAt = state.lastRollAt || -9999;
    up.moveSpdCount = (p.actor && p.actor.moveSpdCount) || 0;
    up.saraivadaLevel = state.saraivadaLevel || 0;
    up.lastSaraivadaAt = state.lastSaraivadaAt || -99999;
    up.balaTranslucida = !!state.balaTranslucida;
    p.upgrades = up;
    syncOnlineScoreAliases();
  }

  function withOnlineShooterContext(pinfo, fn){
    if (!state || !state.onlineCoop || !pinfo) return fn();
    const up = Object.assign(defaultOnlineUpgrades(), pinfo.upgrades || {});
    const old = {
      shotCooldownMs: state.shotCooldownMs,
      bulletSpeed: state.bulletSpeed,
      bulletPierce: state.bulletPierce,
      bulletBounce: state.bulletBounce,
      aimLevel: state.aimLevel,
      target: state.target,
      balaTranslucida: state.balaTranslucida
    };
    state.shotCooldownMs = up.shotCooldownMs;
    state.bulletSpeed = up.bulletSpeed;
    state.bulletPierce = up.bulletPierce;
    state.bulletBounce = up.bulletBounce;
    state.aimLevel = up.aimLevel;
    state.target = pinfo.target || null;
    state.balaTranslucida = !!up.balaTranslucida;
    try{ return fn(); }
    finally{
      Object.assign(state, old);
    }
  }

  function setupOnlinePlayers(session){
    const playersObj = (session && session.players) || {};
    const entries = Object.keys(playersObj).map((id)=>Object.assign({ id:id }, playersObj[id])).filter((p)=>p && p.slot);
    entries.sort((a,b)=>((a.slot||0)-(b.slot||0)));
    const gx = state.gold.x, gy = state.gold.y;
    state.onlinePlayers = entries.map((p)=>{
      let actor;
      if (p.slot === 1) actor = state.player;
      else if (p.slot === 2){
        if (!state.player2) state.player2 = makeOnlineActor(2, gx, gy);
        actor = state.player2;
      } else {
        actor = makeOnlineActor(p.slot, gx, gy);
      }
      actor.name = p.name || ("Cowboy " + p.slot);
      actor.onlineId = p.id;
      return {
        id:p.id,
        slot:p.slot,
        name:p.name || ("Cowboy " + p.slot),
        skin:Number.isFinite(Number(p.skin)) ? (Number(p.skin)|0) : 0,
        aura:Number.isFinite(Number(p.aura)) ? (Number(p.aura)|0) : -1,
        kill:Number.isFinite(Number(p.kill)) ? (Number(p.kill)|0) : 0,
        nameStyle:Number.isFinite(Number(p.nameStyle)) ? (Number(p.nameStyle)|0) : 0,
        connected:p.connected !== false,
        isHost:!!p.isHost,
        actor:actor,
        score:Number.isFinite(Number(p.score)) ? (Number(p.score)|0) : 0,
        totalScore:Number.isFinite(Number(p.totalScore)) ? (Number(p.totalScore)|0) : 0,
        upgrades:Object.assign(defaultOnlineUpgrades(), p.upgrades || {}),
        lastShotAt:-9999,
        reviveProgress:0
      };
    });
    state.coop = true;
    state.currentSkin1 = (state.onlinePlayers.find((p)=>p.slot===1)?.skin) || state.currentSkin || 0;
    const p2 = state.onlinePlayers.find((p)=>p.slot===2);
    state.currentSkin2 = p2 ? p2.skin : -1;
    state.keysHeld2 = state.keysHeld2 || {up:false,down:false,left:false,right:false,shoot:false};
    syncOnlineScoreAliases();
    const local = onlineLocalPlayer();
    state.activeShopPlayer = (local && local.slot) || 1;
    loadOnlineShopContext(local || state.onlinePlayers[0]);
  }

  function syncOnlineRoomPlayers(playersObj){
    if (!state || !state.onlineCoop || !state.onlinePlayers || !playersObj) return;
    const connectedById = {};
    Object.keys(playersObj || {}).forEach(function(id){
      const p = playersObj[id];
      if (p && p.connected !== false) connectedById[id] = p;
    });
    const beforeLocal = onlineLocalPlayer();
    state.onlinePlayers = state.onlinePlayers.filter(function(p){
      if (!p || !p.id) return false;
      const roomPlayer = connectedById[p.id];
      if (!roomPlayer) return false;
      p.connected = true;
      p.name = roomPlayer.name || p.name;
      p.skin = Number.isFinite(Number(roomPlayer.skin)) ? (Number(roomPlayer.skin)|0) : p.skin;
      p.aura = Number.isFinite(Number(roomPlayer.aura)) ? (Number(roomPlayer.aura)|0) : p.aura;
      p.kill = Number.isFinite(Number(roomPlayer.kill)) ? (Number(roomPlayer.kill)|0) : p.kill;
      p.nameStyle = Number.isFinite(Number(roomPlayer.nameStyle)) ? (Number(roomPlayer.nameStyle)|0) : p.nameStyle;
      if (p.actor) p.actor.name = p.name;
      return true;
    });
    state.onlinePlayers.sort((a,b)=>((a.slot||0)-(b.slot||0)));
    if (state.onlineRole === 'client' && beforeLocal && !onlinePlayerById(beforeLocal.id)){
      try{ stopOnlineGameToLobby(); }catch(_){}
      return;
    }
    syncOnlineScoreAliases();
    loadOnlineShopContext(onlineLocalPlayer() || state.onlinePlayers[0]);
    try{ updateHUD(); }catch(_){}
  }

