  // === Multi-kill helpers ===
  function multiLabel(n){
    if (n<=1) return "";
    return "Abate x"+n;
  }
  // cores únicas (2..20): x2 discreto; x3+ sobe de verde neon até ápice branco/dourado.
  const MULTI_COLORS = {
    2:"#25c45a", 3:"#57ff6a", 4:"#00ff88", 5:"#00ffaa",
    6:"#00ffd5", 7:"#00e5ff", 8:"#00a2ff", 9:"#4d7cff",
    10:"#7c4dff", 11:"#b84dff", 12:"#ff4df0", 13:"#ff3bb5",
    14:"#ff3b6a", 15:"#ff3b3b", 16:"#ff7a18", 17:"#ffb000",
    18:"#ffe600", 19:"#fff86b", 20:"#ffe87a"
  };
  function multiColor(n){ return MULTI_COLORS[Math.max(2, Math.min(20, n))] || "#fff"; }
  function multiSound(n){
    n = Math.max(2, Math.min(20, n|0));
    const lift = Math.min(19, n - 2);
    const root = 390 + lift * 22;
    try{
      if (n === 2){
        beep(440,0.04,"sine",0.035);
        setTimeout(()=>beep(587,0.055,"triangle",0.04),45);
        setTimeout(()=>beep(740,0.075,"sine",0.042),98);
        return;
      }
      const gain = Math.min(0.12, 0.045 + n * 0.004);
      if(n===20){
        const finalGain = Math.min(0.13, gain + 0.012);
        const chord = (base, dur, type, g)=>{
          beep(base, dur, type, g);
          beep(base*1.25, dur, "triangle", g*0.55);
        };
        beep(392,0.045,"square",finalGain*0.9);
        setTimeout(()=>chord(523,0.060,"triangle",finalGain),48);
        setTimeout(()=>chord(659,0.070,"triangle",finalGain*0.95),112);
        setTimeout(()=>beep(784,0.080,"sine",finalGain*0.82),184);
        setTimeout(()=>chord(659,0.105,"triangle",finalGain*0.9),260);
        setTimeout(()=>beep(988,0.12,"sine",finalGain*0.45),350);
        return;
      }
      if(n>=17){
        const finalGain = Math.min(0.13, gain + 0.015);
        const root = n>=20 ? 392 : (n>=19 ? 370 : 349);
        beep(root,0.055,"triangle",finalGain);
        setTimeout(()=>beep(root*1.25,0.055,"triangle",finalGain*0.95),58);
        setTimeout(()=>beep(root*1.5,0.070,"square",finalGain*0.85),118);
        setTimeout(()=>beep(root*2,0.095,"sine",finalGain),190);
        setTimeout(()=>beep(root*1.5,0.12,"triangle",finalGain*0.9),285);
        if(n>=20) setTimeout(()=>beep(root*2.5,0.16,"sine",finalGain*0.82),395);
        return;
      }
      beep(root,0.045,"square",gain);
      setTimeout(()=>beep(root+120,0.055,"triangle",gain),42);
      setTimeout(()=>beep(root+240,0.070,"triangle",gain+0.01),92);
      setTimeout(()=>beep(root+360,0.095,"sine",gain+0.015),152);
      if(n>=7) setTimeout(()=>beep(root+520,0.13,"sine",gain+0.02),230);
      if(n>=12) setTimeout(()=>beep(root+700,0.18,"triangle",gain+0.025),330);
      if(n>=17) setTimeout(()=>beep(root+920,0.24,"sine",gain+0.03),470);
    }catch(_){}
  }
  function pushMultiPopup(text, color, x, y, opts){
    opts = (opts && typeof opts === 'object') ? opts : {};
    const life = opts.life || 1.0;
    state.multiPopups.push({text, color, x, y, vy: opts.vy || -16, life: life, max: opts.max || life, showWhilePaused: opts.showWhilePaused === true});
  }
  function pushSyncedPopup(text, color, x, y){
    pushMultiPopup(text, color, x, y);
    emitOnlineAudioEvent('popup', { text:text, color:color, x:x, y:y });
  }
  function playMultiKillFeedback(n, ax, ay, fxX, fxY){
    n = Math.max(2, Math.min(20, n|0));
    pushMultiPopup(multiLabel(n), multiColor(n), ax, ay);
    multiSound(n);
    if(n===2) return;
    const color = multiColor(n);
    const hotColor = n >= 20 ? '#ffffff' : n >= 17 ? '#ffe87a' : n >= 12 ? '#fff86b' : '#ffffff';
    const ox = Number.isFinite(Number(fxX)) ? Number(fxX) : ax;
    const oy = Number.isFinite(Number(fxY)) ? Number(fxY) : ay;
    const intensity = Math.min(1, (n - 3) / 17);
    state.multiFlashT=Math.max(state.multiFlashT||0,0.5+n*0.045);
    state.multiFlashColor=n >= 20 ? '#fff2a8' : color;
    state.multiFlashAlpha=Math.min(0.82,0.16+(n-3)*0.035);
    const ringCount = Math.min(74, 10+n*3);
    for(let i=0;i<ringCount;i++){
      const ang=(Math.PI*2*i)/ringCount;
      const spd=(2.4+Math.random()*4.2*(0.45+intensity))*60;
      const life=0.34+Math.random()*0.42+intensity*0.2;
      const c=n>=20 ? (i%2===0?'#ffffff':'#ffe87a') : (i%5===0?hotColor:color);
      state.fx.push({x:ox,y:oy,vx:Math.cos(ang)*spd,vy:Math.sin(ang)*spd-38,life,max:life,color:c,size:2+Math.random()*3.4+intensity*2.2,grav:135});
    }
    if(n>=6){
      const starCount = Math.min(42, 6+n*2);
      for(let i=0;i<starCount;i++){
        const ang=Math.random()*Math.PI*2;
        const spd=(65+Math.random()*180)*(0.75+intensity*0.8);
        const life=0.32+Math.random()*0.5;
        const starColor = n>=20 ? (i%3===0?'#ffffff':'#ffd36a') : (i%3===0?hotColor:color);
        state.fx.push({x:ox+(Math.random()-0.5)*18,y:oy+(Math.random()-0.5)*12,vx:Math.cos(ang)*spd,vy:Math.sin(ang)*spd-70,life,max:life,color:starColor,size:2.5+Math.random()*4+intensity*3,grav:95,_circle:true});
      }
    }
    if(n>=10){
      const burstCount = Math.min(44, n*2);
      for(let i=0;i<burstCount;i++){
        const ang=(Math.PI*2*i)/burstCount + Math.random()*0.08;
        const spd=(160+Math.random()*170)*(0.75+intensity);
        const life=0.24+Math.random()*0.18;
        const burstColor = n>=20 ? (i%2?'#ffffff':'#f3d23b') : (i%2?color:hotColor);
        state.fx.push({x:ox,y:oy,vx:Math.cos(ang)*spd,vy:Math.sin(ang)*spd-12,life,max:life,color:burstColor,size:1.8+intensity*2.4,grav:30});
      }
    }
    if(n>=20){
      for(let i=0;i<28;i++){
        const ang=Math.random()*Math.PI*2;
        const spd=45+Math.random()*115;
        const life=0.55+Math.random()*0.38;
        state.fx.push({x:ox+(Math.random()-0.5)*24,y:oy+(Math.random()-0.5)*16,vx:Math.cos(ang)*spd,vy:Math.sin(ang)*spd-95,life,max:life,color:i%2?'#ffffff':'#ffe87a',size:4+Math.random()*5,grav:70,_circle:true});
      }
    }
  }
  function scoreSourceForBullet(b){
    if (!b) return null;
    if (b.ownerId) return 'online:' + b.ownerId;
    return b.src || null;
  }
  function multiKillActorOrigin(src, fallbackX, fallbackY){
    let actor = null;
    if (typeof src === 'string' && src.indexOf('online:') === 0){
      const op = onlinePlayerById(src.slice(7));
      actor = op && op.actor;
    } else if (src === 'player2'){
      actor = state.player2;
    } else if (src === 'player'){
      actor = state.player1 || state.player;
    }
    if (actor && Number.isFinite(Number(actor.x)) && Number.isFinite(Number(actor.y))){
      return { x: actor.x*TILE+TILE/2, y: actor.y*TILE+TILE/2 };
    }
    return { x: fallbackX, y: fallbackY };
  }
  function multiKillBucketFor(src){
    if (!state.multiKillBuckets) state.multiKillBuckets = {};
    const key = String(src || 'neutral');
    if (!state.multiKillBuckets[key]) state.multiKillBuckets[key] = {count:0,lastAt:0,baseSum:0,sx:0,sy:0,windowMs:(state.multiKill&&state.multiKill.windowMs)||250,src:src||null};
    return state.multiKillBuckets[key];
  }
  function registerMultiKill(basePoints, tx, ty, src){
    const now = performance.now();
    const mk = state.onlineCoop ? multiKillBucketFor(src) : state.multiKill;
    if (now - mk.lastAt <= mk.windowMs){
      if (mk.src == null && src != null) mk.src = src;
      mk.count += 1;
      mk.baseSum += basePoints;
      mk.sx += (tx || 0); mk.sy += (ty || 0);
    } else {
      // finaliza janela anterior (se houver) antes de iniciar outra
      finalizeMultiKill(state.onlineCoop ? src : null);
      mk.count = 1;
      mk.baseSum = basePoints;
      mk.sx = (tx || 0);
      mk.sy = (ty || 0);
      mk.src = src || null;
    }
    mk.lastAt = now;
  }
  function triggerSegundaChanceOrGameOver(){if(state.secondChance){state.secondChance=false;state.gold.hp=50;state.goldInvulT=3.0;try{const gx=state.gold.x*TILE+TILE/2,gy=state.gold.y*TILE+TILE/2;for(let i=0;i<40;i++){const a=(Math.PI*2*i)/40,s=3+Math.random()*5,l=0.6+Math.random()*0.6;state.fx.push({x:gx,y:gy,vx:Math.cos(a)*s*60,vy:Math.sin(a)*s*60-40,life:l,max:l,color:i%3===0?'#f3d23b':(i%3===1?'#ffffff':'#e0a257'),size:2+Math.random()*4,grav:80});}}catch(_){}state.secondChanceFlashT=1.0;state.shakeT=Math.min(1.0,(state.shakeT||0)+0.8);state.shakeMag=Math.max(8.0,state.shakeMag||0);try{beep(200,0.06,'sawtooth',0.07);setTimeout(()=>beep(400,0.08,'square',0.07),80);setTimeout(()=>beep(600,0.08,'triangle',0.07),160);setTimeout(()=>beep(800,0.10,'triangle',0.08),250);setTimeout(()=>beep(1000,0.12,'triangle',0.09),350);setTimeout(()=>beep(1200,0.18,'triangle',0.10),470);}catch(_){}pushMultiPopup('⚡ SEGUNDA CHANCE!','#f3d23b',state.gold.x*TILE+TILE/2,state.gold.y*TILE-18);toastMsg('⚡ SEGUNDA CHANCE! Ouro restaurado para 50!');try{updateHUD();}catch(_){}}else{state.running=false;musicStop();try{window._expSystem&&window._expSystem.onGameOver(state,'gold');}catch(_){}}}

  function finalizeMultiKill(src){
    const mk = state.onlineCoop && src != null ? multiKillBucketFor(src) : state.multiKill;
    if(mk.count>=2){
      const n=Math.min(20,mk.count);
      const scoreSrc = state.onlineCoop ? (mk.src || src || 'multi') : 'multi';
      addScore(scoreSrc,mk.baseSum*(n-1));
      const ax=(mk.sx/mk.count)*TILE+TILE/2,ay=(mk.sy/mk.count)*TILE+8;
      const fxOrigin = multiKillActorOrigin(mk.src || src, ax, ay);
      playMultiKillFeedback(n, ax, ay, fxOrigin.x, fxOrigin.y);
      if(state.onlineCoop && state.onlineRole==='host') emitOnlineAudioEvent('multi-kill', { n:n, x:ax, y:ay, fxX:fxOrigin.x, fxY:fxOrigin.y });
    }
    mk.count=0;mk.baseSum=0;mk.sx=0;mk.sy=0;mk.src=null;
  }
  function finalizeExpiredMultiKills(){
    const now = performance.now();
    if (state.onlineCoop && state.multiKillBuckets){
      for (const key in state.multiKillBuckets){
        const mk = state.multiKillBuckets[key];
        if (mk && mk.count>0 && now - mk.lastAt > mk.windowMs) finalizeMultiKill(mk.src || key);
      }
      return;
    }
    if (state.multiKill && state.multiKill.count>0 && now - state.multiKill.lastAt > state.multiKill.windowMs) finalizeMultiKill();
  }

  function playPortalTeleportFeedback(tileX, tileY){
    const x = Number(tileX), y = Number(tileY);
    if (Number.isFinite(x) && Number.isFinite(y) && state && state.fx){
      const pcx = x*TILE + TILE/2;
      const pcy = y*TILE + TILE/2;
      for(let pi=0; pi<18; pi++){
        const a = Math.random()*Math.PI*2;
        const s = 60 + Math.random()*90;
        const l = 0.22 + Math.random()*0.22;
        state.fx.push({
          x:pcx, y:pcy,
          vx:Math.cos(a)*s,
          vy:Math.sin(a)*s-30,
          life:l,
          max:l,
          color:pi%3===0?'#ffffff':pi%3===1?'#60c0ff':'#ffb060',
          size:1.5+Math.random()*2.5,
          grav:60
        });
      }
    }
    try{
      beep(440,0.05,'sine',0.05);
      setTimeout(()=>beep(880,0.07,'sine',0.07),60);
      setTimeout(()=>beep(1320,0.09,'triangle',0.08),120);
    }catch(_){}
  }

  function applyPortalTeleportForActor(p, dir, sourceId, broadcast){
    if (!p || !dir || !(state && state.portals && state.portals.blue && state.portals.orange)) return false;
    const pb = state.portals.blue;
    const po = state.portals.orange;
    let dest = null;
    let entrySide = null;
    if (p.x === pb.x && p.y === pb.y && !p._justTeleported){
      dest = po;
      entrySide = {x:dir.x, y:dir.y};
    } else if (p.x === po.x && p.y === po.y && !p._justTeleported){
      dest = pb;
      entrySide = {x:dir.x, y:dir.y};
    }
    if (dest && entrySide){
      const ex = dest.x + entrySide.x;
      const ey = dest.y + entrySide.y;
      if (inBounds(ex, ey) && !isBlocked(ex, ey)){
        p.x = ex;
        p.y = ey;
      } else {
        p.x = dest.x;
        p.y = dest.y;
      }
      p._justTeleported = true;
      playPortalTeleportFeedback(p.x, p.y);
      if (broadcast && state.onlineCoop && state.onlineRole === 'host'){
        emitOnlineAudioEvent('portal-teleport', { sourceId:sourceId || null, x:p.x, y:p.y });
      }
      return true;
    }
    if (p.x !== pb.x || p.y !== pb.y){
      if (p.x !== po.x || p.y !== po.y) p._justTeleported = false;
    }
    return false;
  }

  function predictOnlineClientMove(k){
    if (!(state && state.onlineCoop && state.onlineRole === 'client')) return false;
    const op = onlineLocalPlayer();
    const p = (op && op.actor) || state.player;
    if (!p || p.hp <= 0 || p.moveLock) return true;
    const now = performance.now();
    if (now < (p.nextMoveAt || 0)) return true;
    let dir = null;
    if (k==="w" || k==="W" || k==="ArrowUp") dir = DIRS.up;
    if (k==="s" || k==="S" || k==="ArrowDown") dir = DIRS.down;
    if (k==="a" || k==="A" || k==="ArrowLeft") dir = DIRS.left;
    if (k==="d" || k==="D" || k==="ArrowRight") dir = DIRS.right;
    if (!dir) return true;
    const _gsm = window._gameSettings || {};
    if ((_gsm.inputMode || 'mouse') === 'keys') p.face = dir;
    const nx = p.x + dir.x;
    const ny = p.y + dir.y;
    let blocked = isBlocked(nx, ny) || isBridgeMoveBlocked(p.x, p.y, nx, ny);
    if (!blocked && state.boss && state.boss.alive && nx === state.boss.x && ny === state.boss.y) blocked = true;
    if (!blocked && state.boss2 && state.boss2.alive && nx === state.boss2.x && ny === state.boss2.y) blocked = true;
    if (!blocked){
      p.x = nx;
      p.y = ny;
      applyPortalTeleportForActor(p, dir, state.onlineClientId, false);
      p.nextMoveAt = now + (p.moveLockMs || 220);
      state._onlineLocalPredictAt = now;
    }
    return true;
  }

  function tryMove(k){
    if (state && state.onlineCoop && state.onlineRole === 'client') { predictOnlineClientMove(k); return; }
    const p = state.player;
    // Do not move if the cowboy is down (HP zero)
    if (p && p.hp <= 0) return;
    if (p.moveLock) return; // usado para travas "lógicas" (dialogo/pause/etc)
    const now = performance.now();
    if (now < (p.nextMoveAt||0)) return;

    let dir = null;
    if (k==="w" || k==="W" || k==="ArrowUp") dir = DIRS.up;
    if (k==="s" || k==="S" || k==="ArrowDown") dir = DIRS.down;
    if (k==="a" || k==="A" || k==="ArrowLeft") dir = DIRS.left;
    if (k==="d" || k==="D" || k==="ArrowRight") dir = DIRS.right;
    if (!dir) return;
    // Em modo Apenas Teclado, a direção do movimento define o face
    const _gsm = window._gameSettings || {};
    if ((_gsm.inputMode || 'mouse') === 'keys') p.face = dir;
    const nx = p.x + dir.x;
    const ny = p.y + dir.y;
    // Prevent walking through the other player in local coop. We need to know
    // which cowboy is moving; state.player1 references the original single‑player
    // cowboy, and state.player2 references the partner. When local coop is active
    // and both players exist, block movement into the other player's tile.
    let blocked = isBlocked(nx,ny) || isBridgeMoveBlocked(p.x,p.y,nx,ny);
    // Boss bloqueia passagem do jogador
    if (!blocked && state && state.boss && state.boss.alive && nx===state.boss.x && ny===state.boss.y) blocked=true;
    if (!blocked && state && state.boss2 && state.boss2.alive && nx===state.boss2.x && ny===state.boss2.y) blocked=true;
    if (!blocked) blocked = cowboyOccupiesTile(nx, ny, p);
    if (!blocked && state && state.coop && !state.onlineCoop && state.player2){
      const other = (state.player === state.player1) ? state.player2 : state.player1;
      if (other && nx === other.x && ny === other.y){
        blocked = true;
      }
    }
    if (!blocked){
      p.x = nx; p.y = ny;
      p.nextMoveAt = now + (p.moveLockMs||220);
      // ─── Teleporte via portal (side-aware) ─────────────────────
      const onlineOwner = state.onlineCoop ? ((getOnlinePlayerByActor(p) || {}).id || null) : null;
      applyPortalTeleportForActor(p, dir, onlineOwner, true);
    }
  }


  
  function tileOccupiedByEnemy(x,y){
    // Boss
    if (state.boss && state.boss.alive && state.boss.x===x && state.boss.y===y) return true;
    // Inimigos
    for (const z of state.bandits){
      if (!z.alive) continue;
      if (z.x===x && z.y===y) return true;
    }
    return false;
  }

  function rollDistanceTiles(){
    const lvl = state.rollLevel||0;
    if (lvl<=0) return 0;
    if (lvl===1) return 2;
    if (lvl===2) return 4;
    return 6;
  }

  function rollCooldownMsForLevel(level){
    const lvl = Math.max(0, Math.min(3, level|0));
    if (lvl <= 0) return 2000;
    if (lvl === 1) return 2000;
    if (lvl === 2) return 1500;
    return 1000;
  }

  function activeRollCooldownMs(level, fallbackMs){
    const lvl = Math.max(0, Math.min(3, level|0));
    if (lvl > 0) return rollCooldownMsForLevel(lvl);
    return (typeof fallbackMs === 'number' && isFinite(fallbackMs)) ? fallbackMs : 2000;
  }

  function sfxRoll(){
    try{
      // "whoosh" + clickzinho
      noise(0.06, 0.03);
      beep(620, 0.03, "sine", 0.06);
      beep(980, 0.05, "triangle", 0.05);
    }catch(_){}
  }

  function spawnRollTrail(px, py, dir){
    // trilha azul bem marcada (partículas)
    const cx = px * TILE + TILE/2;
    const cy = py * TILE + TILE/2;
    for (let i=0;i<8;i++){
      const spread = 0.45;
      const ang = Math.atan2(-dir.y, -dir.x) + (Math.random()-0.5)*spread;
      const spd = 120 + Math.random()*180;
      const life = 0.18 + Math.random()*0.10;
      state.fx.push({
        x: cx + (Math.random()-0.5)*6,
        y: cy + (Math.random()-0.5)*6,
        vx: Math.cos(ang)*spd,
        vy: Math.sin(ang)*spd,
        life, max: life,
        color: (i%3===0) ? "#b9ecff" : "#3da1ff",
        size: 2,
        grav: 0
      });
    }
  }

  function onlineActorForEventSource(sourceId){
    try{
      const op = sourceId ? onlinePlayerById(sourceId) : null;
      if (op && op.actor) return op.actor;
      if (state && sourceId && sourceId === state.onlineClientId) return state.player;
    }catch(_){}
    return null;
  }

  function triggerOnlineRollFeedback(sourceId, x, y, dir, playSound){
    if (!state) return;
    dir = dir || DIRS.up;
    x = Number.isFinite(x) ? x : 0;
    y = Number.isFinite(y) ? y : 0;
    try{
      for (let i=0; i<4; i++){
        spawnRollTrail(x - dir.x * i, y - dir.y * i, dir);
      }
      if (playSound) sfxRoll();
      state.shakeT = Math.max(state.shakeT || 0, 0.05);
      state.shakeMag = Math.max(state.shakeMag || 0, 1.1);
    }catch(_){}
  }

  function triggerOnlineSaraivadaFeedback(sourceId, x, y, playSound){
    if (!state) return;
    if (!state._onlineSaraivadaFx) state._onlineSaraivadaFx = [];
    const now = performance.now();
    const fx = {
      sourceId: sourceId || null,
      x: Number.isFinite(x) ? x : null,
      y: Number.isFinite(y) ? y : null,
      startAt: now,
      flashEndAt: now + 220,
      spinEndAt: now + 320
    };
    state._onlineSaraivadaFx = state._onlineSaraivadaFx.filter(function(old){
      return old && old.sourceId !== fx.sourceId && (old.flashEndAt > now || old.spinEndAt > now);
    });
    state._onlineSaraivadaFx.push(fx);
    if (playSound) playSaraivadaSfx();
  }

  function activeOnlineSaraivadaFx(sourceId){
    if (!state || !state._onlineSaraivadaFx || !sourceId) return null;
    const now = performance.now();
    for (let i=state._onlineSaraivadaFx.length-1; i>=0; i--){
      const fx = state._onlineSaraivadaFx[i];
      if (fx && fx.sourceId === sourceId && (fx.flashEndAt > now || fx.spinEndAt > now)) return fx;
    }
    return null;
  }

  function onlineSaraivadaRenderFace(sourceId, fallback){
    const fx = activeOnlineSaraivadaFx(sourceId);
    if (!fx || fx.spinEndAt <= performance.now()) return fallback || DIRS.up;
    const prog = Math.max(0, Math.min(1, (performance.now() - fx.startAt) / 320));
    const phase = Math.floor(prog * 12) % 8;
    const dirs8 = [{x:0,y:-1},{x:1,y:-1},{x:1,y:0},{x:1,y:1},{x:0,y:1},{x:-1,y:1},{x:-1,y:0},{x:-1,y:-1}];
    return dirs8[phase] || fallback || DIRS.up;
  }

  function drawOnlineSaraivadaFx(ctx){
    if (!state || !state._onlineSaraivadaFx || !state._onlineSaraivadaFx.length) return;
    const now = performance.now();
    const next = [];
    for (const fx of state._onlineSaraivadaFx){
      if (!fx || (fx.flashEndAt <= now && fx.spinEndAt <= now)) continue;
      next.push(fx);
      if (fx.flashEndAt <= now) continue;
      const actor = onlineActorForEventSource(fx.sourceId);
      const tx = actor ? actor.x : fx.x;
      const ty = actor ? actor.y : fx.y;
      if (!Number.isFinite(tx) || !Number.isFinite(ty)) continue;
      const a = Math.max(0, Math.min(1, (fx.flashEndAt - now) / 220));
      ctx.save();
      ctx.globalAlpha = a * 0.75;
      ctx.strokeStyle = '#f3d23b';
      ctx.lineWidth = 3.5;
      ctx.shadowColor = '#ffe066';
      ctx.shadowBlur = 10;
      ctx.beginPath();
      ctx.arc(tx*TILE + TILE/2, ty*TILE + TILE/2, TILE*0.72, 0, Math.PI*2);
      ctx.stroke();
      ctx.restore();
    }
    state._onlineSaraivadaFx = next;
  }

  function playOnlineClientRollFeedback(){
    if (!(state && state.onlineCoop && state.onlineRole === 'client')) return false;
    if (!state.running || state.inMenu || state.pausedShop || state.pausedManual || state.onlineHostPaused || isDialogBlockingGameplay()) return true;
    const up = onlineLocalUpgrades();
    if ((up.rollLevel || 0) <= 0) return true;
    const lc = onlineClientCooldownState();
    const now = performance.now();
    const cd = activeRollCooldownMs(up.rollLevel || 0, up.rollCooldownMs || 2000);
    if (now - (lc.lastRollAt || -9999) < cd) return true;
    const op = onlineLocalPlayer();
    const p = (op && op.actor) || state.player;
    if (!p || p.hp <= 0) return true;
    const oldRollLevel = state.rollLevel;
    state.rollLevel = up.rollLevel || 0;
    const dist = rollDistanceTiles();
    state.rollLevel = oldRollLevel;
    if (!dist) return true;
    let dir = p.face || DIRS.up;
    if (state.keysHeld){
      if (state.keysHeld.up) dir = DIRS.up;
      else if (state.keysHeld.down) dir = DIRS.down;
      else if (state.keysHeld.left) dir = DIRS.left;
      else if (state.keysHeld.right) dir = DIRS.right;
    }
    let tx = p.x, ty = p.y;
    let steps = 0;
    for (let i=0;i<dist;i++){
      const nx = tx + dir.x;
      const ny = ty + dir.y;
      if (isBlocked(nx,ny) || isBridgeMoveBlocked(tx,ty,nx,ny) || tileOccupiedByEnemy(nx,ny) || cowboyOccupiesTile(nx, ny, p)) break;
      tx = nx; ty = ny; steps++;
      spawnRollTrail(tx, ty, dir);
    }
    if (steps > 0){
      lc.lastRollAt = now;
      lc.rollHeld = true;
      state.rollFlash = Math.max(state.rollFlash || 0, 0.28);
      state.rollAnimT = 0.32;
      sfxRoll();
      state.shakeT = Math.max(state.shakeT || 0, 0.06);
      state.shakeMag = Math.max(state.shakeMag || 0, 1.4);
      try{ updateHUD(); }catch(_){}
    }
    return true;
  }

  function tryRoll(){
    if (state && state.onlineCoop && state.onlineRole === 'client') { playOnlineClientRollFeedback(); return; }
    if (!state || !state.running || state.inMenu) return;
    if (state.pausedShop || state.pausedManual) return;
    if (isDialogBlockingGameplay()) return;
    if (!(state.rollLevel>0)) return;

    // Prevent rolling when the cowboy is down (HP zero)
    if (state.player && state.player.hp <= 0) return;

    const now = performance.now();
    if (now - (state.lastRollAt||-9999) < activeRollCooldownMs(state.rollLevel || 0, state.rollCooldownMs || 2000)) return;

    const p = state.player;
    if (!p) return;
    const dist = rollDistanceTiles();
    if (!dist) return;

    // Direção do rolamento: prioriza tecla pressionada no momento; senão usa a face atual
    let dir = p.face || DIRS.up;
    if (state.keysHeld){
      if (state.keysHeld.up) dir = DIRS.up;
      else if (state.keysHeld.down) dir = DIRS.down;
      else if (state.keysHeld.left) dir = DIRS.left;
      else if (state.keysHeld.right) dir = DIRS.right;
    }
    // p.face is controlled by mouse aim
// Rolamento nao usa moveLock por tempo (evita bug de velocidade)

    // executa deslocamento tile-a-tile, parando em obstáculo/inimigo
    let steps = 0;
    for (let i=0;i<dist;i++){
      const nx = p.x + dir.x;
      const ny = p.y + dir.y;
      if (isBlocked(nx,ny) || isBridgeMoveBlocked(p.x,p.y,nx,ny) || tileOccupiedByEnemy(nx,ny) || cowboyOccupiesTile(nx, ny, p)) break;
      p.x = nx; p.y = ny;
      steps++;
      spawnRollTrail(p.x, p.y, dir);
    }

    if (steps>0){
      state.lastRollAt = now;
      // evita 'boost' de movimento logo apos rolar
      state.lastMoveAt = now;
      state.player.nextMoveAt = now + (state.player.moveLockMs||220);
      state.rollFlash=Math.max(state.rollFlash||0,0.28);state.rollAnimT=0.32;
      sfxRoll();
      // micro screenshake "bom" (não incomoda)
      state.shakeT = Math.max(state.shakeT||0, 0.06);
      state.shakeMag = Math.max(state.shakeMag||0, 1.4);
      if (state.onlineCoop && state.onlineRole === 'host'){
        emitOnlineAudioEvent('roll', {
          sourceId:state._onlineRollSourceId || state.onlineClientId || null,
          x:p.x, y:p.y,
          dirX:dir.x, dirY:dir.y,
          shakeT:0.05, shakeMag:1.1
        });
      }
    }
  }


function doSaraivada(){
  if (!state || !state.running) return;
  if (state.onlineCoop && state.onlineRole === 'client'){
    if (state.inMenu || state.pausedShop || state.pausedManual || state.onlineHostPaused || isDialogBlockingGameplay()) return;
    const up = onlineLocalUpgrades();
    const lc = onlineClientCooldownState();
    if (!up || !lc || (up.saraivadaLevel || 0) <= 0) return;
    const actor = (onlineLocalPlayer() && onlineLocalPlayer().actor) || state.player;
    if (actor && actor.hp <= 0) return;
    const nowClient = performance.now();
    const cdClient = saraivadaCooldownMs(up.saraivadaLevel || 0, up.shotCooldownMs || state.shotCooldownMs || 750);
    if (nowClient - (lc.lastSaraivadaAt || -99999) < cdClient) return;
    lc.lastSaraivadaAt = nowClient;
    state.saraivadaSpinT = 0.32;
    state.saraivadaFlashT = 0.22;
    playSaraivadaSfx();
    onlineSendAction({type:'saraivada'});
    updateHUD();
    return;
  }
  if (!state.saraivadaLevel || state.saraivadaLevel <= 0) return;
  if (state.player && state.player.hp <= 0) return;
  const now = performance.now();
  const cd = saraivadaCooldownMs(state.saraivadaLevel || 0, state.shotCooldownMs || 750);
  if (now - state.lastSaraivadaAt < cd) return;
  state.lastSaraivadaAt = now;
  const p = state.player;
  const cx = p.x * TILE + TILE/2, cy = p.y * TILE + TILE/2;
  // 8 direções: cardinais + diagonais
  const dirs8 = [
    {x:0,y:-1},{x:1,y:-1},{x:1,y:0},{x:1,y:1},
    {x:0,y:1},{x:-1,y:1},{x:-1,y:0},{x:-1,y:-1}
  ];
  for (const d of dirs8){
    const len = Math.hypot(d.x, d.y) || 1;
    const vx = (d.x/len) * state.bulletSpeed;
    const vy = (d.y/len) * state.bulletSpeed;
    state.bullets.push({
      dir: d, px: cx, py: cy,
      vx, vy,
      speed: state.bulletSpeed,
      alive: true,
      pierceLeft: state.bulletPierce,
      bounceLeft: state.bulletBounce,
      dmg: 20,
      src: 'player'
    });
  }
  // Animação: spin do ponteiro + flash
  if (!state._onlineSuppressSaraivadaLocalFx){
    state.saraivadaSpinT = 0.32;
    state.saraivadaFlashT = 0.22;
    // Som: rajada rápida de bipes
    playSaraivadaSfx();
  }
  if (state.onlineCoop && state.onlineRole === 'host'){
    emitOnlineAudioEvent('saraivada', { sourceId:state._onlineSaraivadaSourceId || state.onlineClientId || null, x:p.x, y:p.y });
  }
  updateHUD();
}

