    const _targetPause = (state.running && !state.inMenu && ((state.pausedManual && !state.pausedShop) || _onlineHostPause)) ? 1 : 0;
    const _targetOver = (!state.running && !state.inMenu) ? 1 : 0;
    const _fadeK = Math.min(1, dt * 10);
