      ctx.save();ctx.globalAlpha=0.55;ctx.fillStyle=_inv?'#d94949':'#f3d23b';ctx.fillRect(_hx*TILE+2,_hy*TILE+2,TILE-4,TILE-4);
      ctx.globalAlpha=0.9;ctx.lineWidth=3;ctx.strokeStyle=_inv?'#7a1a1a':'#c97a2b';
