  // === HUD lock helpers for in-game modals (Shop / Confirm Menu) ===
  function __hudLockButtons(){
    try{
      ['shopBtn','menuBackBtn','pauseBtn','ingameOptBtn','p1ShopBtn','p2ShopBtn'].forEach(function(id){
        var b=document.getElementById(id);
        if(b){
          b.disabled = true;
          try{ b.setAttribute('aria-disabled','true'); }catch(_){}
          try{ b.style.pointerEvents='none'; }catch(_){}
        }
      });
    }catch(_){}
  }
  function __hudUnlockButtonsIfNoModal(){
    try{
      const body = document.body;
      const anyOpen =
        (body && body.getAttribute('data-results-open')==='1') ||
        (body && body.getAttribute('data-options-open')==='1') ||
        (body && body.getAttribute('data-shop-open')==='1') ||
        (body && body.getAttribute('data-esc-menu-open')==='1') ||
        (body && body.getAttribute('data-confirm-open')==='1');
      if(anyOpen) return;
      ['shopBtn','menuBackBtn','pauseBtn','ingameOptBtn','p1ShopBtn','p2ShopBtn'].forEach(function(id){
        var b=document.getElementById(id);
        if(b){
          b.disabled = false;
          try{ b.setAttribute('aria-disabled','false'); }catch(_){}
          try{ b.style.pointerEvents=''; }catch(_){}
        }
      });
      try{
        if (state && state.coop && state.running && !state.inMenu){
          syncCoopLocalShopDeathButtons();
        }
      }catch(_){}
    }catch(_){}
  }
// Confirmação para voltar ao menu
  function getOnlineConfirmContext(){
    try{
      const gameState = state || (window.__defendaApi && window.__defendaApi.getState && window.__defendaApi.getState());
      const onlineApi = window.__onlineCoop || null;
      const onlineState = onlineApi && onlineApi.state ? onlineApi.state : null;
      const pendingCtx = window.__defendaPendingOnlineMenuCtx || null;
      const resultCtx = ((typeof _gorOnlineResultContext !== 'undefined') ? _gorOnlineResultContext : null) || window.__gorOnlineResultContext || null;
      const resultPanel = document.getElementById('gameOverResults');
      const panelOnlineActive = !!(resultPanel && resultPanel.classList && resultPanel.classList.contains('gor-visible') && resultPanel.getAttribute('data-online-result') === '1');
      const onlineRoomActive = !!(onlineState && (onlineState.running || onlineState.runId || onlineState.roomCode || (onlineState.room && onlineState.room.status && onlineState.room.status !== 'closed')));
      const gameOnlineActive = !!(gameState && gameState.onlineCoop);
      const resultOnlineActive = !!(resultCtx && resultCtx.onlineCoop);
      const pendingActive = !!(pendingCtx && pendingCtx.at && Date.now() - pendingCtx.at < 30000);
      if (!gameOnlineActive && !onlineRoomActive && !resultOnlineActive && !panelOnlineActive && !pendingActive) return null;
      const panelRole = panelOnlineActive ? resultPanel.getAttribute('data-online-role') : null;
      const role = (pendingActive && pendingCtx.role) || panelRole || (resultCtx && resultCtx.role) || (gameState && gameState.onlineRole) || (onlineState && onlineState.isHost ? 'host' : 'client');
      return { role: role === 'host' ? 'host' : 'client', api: onlineApi, gameState: gameState, onlineState: onlineState };
    }catch(_){
      return null;
    }
  }

  function openConfirmMenu(mode){
    mode = mode || 'menu';
    if (state) state._confirmMenuAction = mode;
    if (state && !state.onlineCoop) state.pausedManual = true;
    try{ document.body.setAttribute('data-confirm-open','1'); }catch(_){ }
    try{ __hudLockButtons(); }catch(_){ }
    try{ const pb=document.getElementById('pauseBtn'); if(pb) pb.textContent=(state && (state.pausedManual||state.pausedShop))?'Despausar':'Pausar'; }catch(_){ }
    try{
      const h=document.getElementById('confirmHeading');
      const p=document.querySelector('#confirmCard p.muted');
      const onlineCtx = mode === 'menu' ? getOnlineConfirmContext() : null;
      if (mode === 'exit'){
        if (h) h.textContent = 'Sair do jogo?';
        if (p) p.textContent = 'O jogo será fechado.';
      } else if (onlineCtx){
        if (h) h.textContent = onlineCtx.role === 'host' ? 'Encerrar partida?' : 'Sair da partida?';
        if (p) p.textContent = onlineCtx.role === 'host'
          ? 'A partida será encerrada e todos voltarão ao lobby online.'
          : 'Você será removido da partida e do lobby online.';
      } else {
        if (h) h.textContent = 'Voltar ao Menu?';
        if (p) p.textContent = 'Seu progresso atual será perdido.';
      }
    }catch(_){}
    const m=document.getElementById("confirmModal"); if(m){ m.style.display="flex"; m.setAttribute("aria-hidden","false"); }
    syncInGameModalMusicDuck();
  }
  function forceOnlineResultMenuConfirm(){
    try{
      const ctx = getOnlineConfirmContext();
      if (!ctx) return false;
      try{ window.__defendaPendingOnlineMenuCtx = { role:ctx.role, at:Date.now() }; }catch(_){}
      openConfirmMenu();
      return true;
    }catch(_){
      return false;
    }
  }
  try{ window.__defendaForceOnlineResultMenuConfirm = forceOnlineResultMenuConfirm; }catch(_){}
  function closeConfirmMenu(reopenEscMenu){
    const shouldReopenEsc = reopenEscMenu !== false && !!(state && state._confirmReturnToEscMenu);
    const escPrevPaused = !!(state && state._confirmEscPrevPausedManual);
    const m=document.getElementById("confirmModal"); if(m){ m.style.display="none"; m.setAttribute("aria-hidden","true"); }
    if (state){
      state.pausedManual = shouldReopenEsc ? true : false;
      state._confirmMenuAction = null;
      state._confirmReturnToEscMenu = false;
    }
    try{ document.body.removeAttribute('data-confirm-open'); }catch(_){ }
    try{ __hudUnlockButtonsIfNoModal(); }catch(_){ }
    try{ const pb=document.getElementById('pauseBtn'); if(pb) pb.textContent=(state && (state.pausedManual||state.pausedShop))?'Despausar':'Pausar'; }catch(_){ }
    if (shouldReopenEsc){
      restoreInGameEscMenuAfterConfirm(escPrevPaused);
      if (state) state._confirmEscPrevPausedManual = null;
    } else {
      syncInGameModalMusicDuck();
      if (state) state._confirmEscPrevPausedManual = null;
    }
  }
  (function(){
    const noBtn = document.getElementById("confirmNo");
    const yesBtn = document.getElementById("confirmYes");
    if (noBtn && !noBtn._bound){ noBtn._bound=true; noBtn.addEventListener("click", ()=>{ closeConfirmMenu(); }); }
    if (yesBtn && !yesBtn._bound){ yesBtn._bound=true; yesBtn.addEventListener("click", ()=>{
      // Confirma: reseta e volta ao menu (progresso perdido)
      const confirmAction = (state && state._confirmMenuAction) || 'menu';
      closeConfirmMenu(false);
      try{ closeInGameEscMenu(); }catch(_){}
      forceCloseDialogForTransition();
      if (confirmAction === 'exit'){
        try{
          if (window.__defendaRequestAppExit) window.__defendaRequestAppExit();
          else if (window.__defendaNativeStore && typeof window.__defendaNativeStore.exitApp === 'function') window.__defendaNativeStore.exitApp();
          else window.close();
        }catch(_){}
        return;
      }
      const onlineCtx = getOnlineConfirmContext();
      if (onlineCtx){
        if (!onlineCtx.api) return;
        if (onlineCtx.role === 'host'){
          try{
            const ret = onlineCtx.api.returnToLobby(true);
            if (ret && ret.catch) ret.catch(function(){});
          }catch(_){}
        } else {
          try{
            const ret = onlineCtx.api.leave(false);
            if (ret && ret.then) ret.then(function(){ try{ onlineCtx.api.open(); }catch(_){}; }).catch(function(){});
            else try{ onlineCtx.api.open(); }catch(_){}
          }catch(_){}
          try{ if (window.__defendaApi && window.__defendaApi.stopOnlineGameToLobby) window.__defendaApi.stopOnlineGameToLobby(); }catch(_){}
        }
        return;
      }
      // If currently in coop, use coop reset to keep both jogadores alive
      if (state && state.coop){
        resetGameCoop();
      } else {
        resetGame();
      }
      // Clear coop state so that returning to the menu resets UI and
      // gameplay back to single‑player mode. Without clearing this flag or
      // removing the secondary cowboy, starting a new solo run after
      // leaving coop could inherit coop HUD elements or leftover data.
      if (state){
        state.coop = false;
        delete state.player2;
      }
      try{ if (window.releaseCoopInputModeLock) window.releaseCoopInputModeLock(); }catch(_){}
      state.running = false;
      state.inMenu = true;
      musicStop();
      showMenu();
    }); }
    // Fechar ao clicar fora do card
    const modal = document.getElementById("confirmModal");
    if (modal && !modal._bound){ modal._bound=true; modal.addEventListener("click", (e)=>{ if (e.target === modal) closeConfirmMenu(); }); }
  })();
  shopModal.addEventListener("click", (e)=>{ if (e.target === shopModal) closeShopModal(); });
