  function showResultUnlockBanner(id){
    var banner=document.getElementById(id);
    if(banner){ banner.style.display='block'; banner.style.animation='none'; void banner.offsetWidth; banner.style.animation='levelPop 0.4s cubic-bezier(0.22,1,0.36,1)'; }
  }

  function animateCoins(target, token){
    var el=document.getElementById('gorCoinsText');
    if(!el){ if(token===_gorAnimToken) gorSetLocked(false); return; }
    var DUR=1500,t0=performance.now(),lastTick=-999;
    (function frame(now){
      if(token!==_gorAnimToken) return;
      var p=Math.min(1,(now-t0)/DUR), cur=Math.round((1-Math.pow(1-p,3))*target);
      el.textContent='+ '+cur.toLocaleString('pt-BR')+' Ouro ganho';
      if(now-lastTick>115&&cur>0){ lastTick=now; sndCoin(); }
      if(p<1){ _gorTrackRaf(token, frame); }
      else if(token===_gorAnimToken){ el.textContent='+ '+target.toLocaleString('pt-BR')+' Ouro ganho'; gorSetLocked(false); }
    })(performance.now());
  }

  function animateBar(preLevel, preExp, expToAdd, coinsGained, token, onLevelUp){
    var curLvl=preLevel, curExp=preExp, rem=expToAdd;
    function segment(fromPct,toPct,dur,done){
      var t0=performance.now(),lastSnd=-999;
      (function frame(now){
        if(token!==_gorAnimToken) return;
        var p=Math.min(1,(now-t0)/dur), ease=p<0.5?2*p*p:-1+(4-2*p)*p, pct=fromPct+(toPct-fromPct)*ease;
        var fill=document.getElementById('gorExpBarFill'), lbl=document.getElementById('gorExpBarLabel');
        if(fill) fill.style.width=pct.toFixed(2)+'%';
        if(lbl){ var needed=expNeeded(curLvl), disp=Math.round(curExp+(pct-fromPct)/(Math.max(0.01,toPct-fromPct))*(toPct/100*needed-curExp)); lbl.textContent=fmtExpNum(Math.max(0,Math.min(needed,disp)))+' / '+fmtExpNum(needed); }
        if(now-lastSnd>=90&&p<0.97){ lastSnd=now; sndTick(pct); }
        if(p<1) _gorTrackRaf(token, frame); else if(token===_gorAnimToken) done();
      })(performance.now());
    }
    function step(){
      if(token!==_gorAnimToken) return;
      var needed=expNeeded(curLvl), space=needed-curExp;
      if(rem<=space){
        var dur=Math.max(500,Math.round(rem/Math.max(1,expToAdd)*1600)+350);
        segment(curExp/needed*100,(curExp+rem)/needed*100,dur,function(){
          if(token!==_gorAnimToken) return;
          var lbl=document.getElementById('gorExpBarLabel'); if(lbl) lbl.textContent=fmtExpNum(curExp+rem)+' / '+fmtExpNum(needed);
          _gorTrackTimeout(token, function(){ animateCoins(coinsGained, token); },350);
        });
      } else {
        var dur2=Math.max(350,Math.round(space/Math.max(1,expToAdd)*1600)+150);
        segment(curExp/needed*100,100,dur2,function(){
          _gorTrackTimeout(token, function(){
            if(token!==_gorAnimToken) return;
            curLvl++; rem-=space; curExp=0;
            var e;
            e=document.getElementById('gorExpLevelLabel'); if(e) e.textContent='Nível '+curLvl;
            e=document.getElementById('gorExpBarFill');    if(e) e.style.width='0%';
            e=document.getElementById('gorExpBarLabel');   if(e) e.textContent='0 / '+fmtExpNum(expNeeded(curLvl));
            var banner=document.getElementById('gorLevelUpBanner');
            if(banner){ banner.style.display='block'; banner.style.animation='none'; void banner.offsetWidth; banner.style.animation='levelPop 0.4s cubic-bezier(0.22,1,0.36,1)'; }
            sndLevelUp(token);
            if(onLevelUp) try{ onLevelUp(curLvl, token); }catch(_){}
            _gorTrackTimeout(token, step,560);
          },220);
        });
      }
    }
    step();
  }

  function animateStatCount(el, from, to, dur, formatFn, tickEveryMs, tickFn, token){
    if(!el){ return new Promise(function(res){res();}); }
    from = Number(from)||0; to = Number(to)||0; dur = Math.max(120, dur||600);
    var t0 = performance.now(), lastTick = -9999;
    var lastTickValue = from;
    return new Promise(function(resolve){
      (function frame(now){
        if(token!==_gorAnimToken){ resolve(); return; }
        var p = Math.min(1, (now - t0) / dur);
        var e = 1 - Math.pow(1 - p, 3);
        var cur = Math.round(from + (to - from) * e);
        el.textContent = formatFn ? formatFn(cur) : String(cur);
        if(tickFn && (now - lastTick) >= (tickEveryMs||85) && cur !== lastTickValue && p < 0.999){
          lastTick = now;
          lastTickValue = cur;
          try{ tickFn(cur, to, p); }catch(_){}
        }
        if(p < 1) _gorTrackRaf(token, frame);
        else { el.textContent = formatFn ? formatFn(to) : String(to); resolve(); }
      })(performance.now());
    });
  }

  function animateResultsPrelude(waves, score, expG, preL, token){
    function $(id){ return document.getElementById(id); }
    var elW = $('gorStatWaves');
    var elS = $('gorStatScore');
    var elE = $('gorStatExp');
    var elGain = $('gorExpGainLabel');

    if(elW) elW.textContent = '0';
    if(elS) elS.textContent = '0';
    if(elE) elE.textContent = '+0';
    if(elGain) elGain.textContent = '+0 EXP';

    function tickCounter(cur, to){
      var pct = to>0 ? (cur/to) : 0;
      try{ window._gameBeep(520 + pct*220 + (Math.random()*40-20), 0.045, 'sine', 0.045); }catch(_){ }
    }

    return animateStatCount(elW, 0, waves, 900, function(v){ return String(v); }, 105, function(){ tickCounter(1,1); }, token)
      .then(function(){
        if(token!==_gorAnimToken) return;
        return animateStatCount(elS, 0, score, 1050, function(v){ return v.toLocaleString('pt-BR'); }, 95, function(cur,to){
          tickCounter(cur,to);
        }, token);
      })
      .then(function(){
        if(token!==_gorAnimToken) return;
        return animateStatCount(elE, 0, expG, 950, function(v){ return '+'+fmtExpNum(v); }, 90, function(cur,to){
          tickCounter(cur,to);
          if(elGain) elGain.textContent = '+'+fmtExpNum(cur)+' EXP';
        }, token).then(function(){
          if(elGain) elGain.textContent = '+'+fmtExpNum(expG)+' EXP';
        });
      });
  }

  function showResults(gs, reason){
    if(gs && gs._gorResultsShown) return;
    if(gs) gs._gorResultsShown = true;
    try{
      var onlineState = window.__onlineCoop && window.__onlineCoop.state ? window.__onlineCoop.state : null;
      var isOnlineResult = !!(gs && gs.onlineCoop) || !!(onlineState && (onlineState.running || onlineState.runId || onlineState.roomCode));
      var onlineRole = (gs && gs.onlineRole) || (onlineState && onlineState.isHost ? 'host' : 'client');
      _gorOnlineResultContext = isOnlineResult ? {
        onlineCoop:true,
        role: onlineRole === 'host' ? 'host' : 'client',
        runId: (gs && gs.onlineRunId) || (onlineState && onlineState.runId) || null,
        roomCode: onlineState && onlineState.roomCode || null
      } : null;
      try{ window.__gorOnlineResultContext = _gorOnlineResultContext; }catch(__){}
    }catch(_){
      _gorOnlineResultContext=null;
      try{ window.__gorOnlineResultContext = null; }catch(__){}
    }
    try{ syncSandboxPanel(); cancelSandboxPlacingEnemy(); }catch(_){}
    _gorCancelPendingAnims();
    var token=_gorAnimToken;
    var waves=Math.max(0,(gs.wave||1)-1);
    function getLocalOnlineResultPlayer(){
      if(!(gs && gs.onlineCoop && Array.isArray(gs.onlinePlayers))) return null;
      var localId=gs.onlineClientId || (gs.onlineRole==='host' ? gs.onlineHostId : null);
      var localPlayer=null;
      for(var i=0;i<gs.onlinePlayers.length;i++){
        var op=gs.onlinePlayers[i];
        if(op && localId && op.id===localId){ localPlayer=op; break; }
      }
      if(!localPlayer && gs.onlinePlayers.length) localPlayer=gs.onlinePlayers[0];
      return localPlayer || null;
    }
    function getLocalOnlineScoreBase(localPlayer){
      if(!(gs && gs.onlineCoop) || !localPlayer) return null;
      var byId = gs.accountCoinsRewardOnlineScoreBaseById || {};
      var bySlot = gs.accountCoinsRewardOnlineScoreBaseBySlot || {};
      if(localPlayer.id && byId[localPlayer.id] != null) return Math.max(0, Number(byId[localPlayer.id]) || 0);
      if(localPlayer.slot != null && bySlot[String(localPlayer.slot)] != null) return Math.max(0, Number(bySlot[String(localPlayer.slot)]) || 0);
      if(localPlayer.slot != null && bySlot[localPlayer.slot] != null) return Math.max(0, Number(bySlot[localPlayer.slot]) || 0);
      return Math.max(0, Number(gs.accountCoinsRewardScoreBase) || 0);
    }
    var localOnlineResultPlayer=getLocalOnlineResultPlayer();
    var onlineScore=localOnlineResultPlayer
      ? Math.max(0, localOnlineResultPlayer.totalScore||localOnlineResultPlayer.score||0)
      : null;
    var score=onlineScore!=null
      ? onlineScore
      : gs.coop
      ? Math.max(0,(gs.totalScore1||0) + (gs.totalScore2||0))
      : Math.max(0, gs.totalScore!=null ? gs.totalScore : (gs.score||0));
    var coinBaseWaves=Math.max(0,gs.accountCoinsRewardWaveBase||0), coinBaseScore=Math.max(0,gs.accountCoinsRewardScoreBase||0);
    if(localOnlineResultPlayer) coinBaseScore = getLocalOnlineScoreBase(localOnlineResultPlayer);
    var rewardWaves=Math.max(0,waves-coinBaseWaves), rewardScore=Math.max(0,score-coinBaseScore);
    var sandboxRun=!!(gs && gs.sandbox && gs.sandbox.enabled);
    var expG=sandboxRun?0:(coinBaseWaves > 0 ? Math.max(0, calcExp(waves) - calcExp(coinBaseWaves)) : calcExp(waves));
    var difficultyReward=accountDifficultyRewardFor(gs && gs.difficulty);
    var baseCoinsG=((rewardWaves>0||rewardScore>0)?calcCoins(rewardWaves,rewardScore):0);
    var coinsG=sandboxRun?0:applyCoinDifficultyMultiplier(baseCoinsG, difficultyReward.key);
    var acc=acctLoad(), preL=acc.level, preE=acc.exp;
    var difficultyKey=normalizeAccountDifficulty(gs && gs.difficulty);
    var difficultyUnlocksThisRun={ hard:false, bizarre:false };
    var boxRewardsThisRun={ common:0, special:0 };
    if(!sandboxRun){
      var boxRewardBaseLevel = Math.max(1, Math.round(Number(acc.lastBoxRewardLevel) || preL));
      acc.exp+=expG; acc.coins+=coinsG;
      while(acc.exp>=expNeeded(acc.level)){ acc.exp-=expNeeded(acc.level); acc.level++; }
      var rewardLevelAfterExp = Math.max(1, acc.level);
      boxRewardsThisRun = grantLevelBoxes(acc, boxRewardBaseLevel, rewardLevelAfterExp);
      acc.difficultyUnlocks = acc.difficultyUnlocks || { hard:false, bizarre:false };
      if(waves >= 100 && difficultyKey === 'normal' && acc.difficultyUnlocks.hard !== true){
        acc.difficultyUnlocks.hard = true;
        difficultyUnlocksThisRun.hard = true;
      }
      if(waves >= 100 && difficultyKey === 'hard' && acc.difficultyUnlocks.bizarre !== true){
        acc.difficultyUnlocks.bizarre = true;
        difficultyUnlocksThisRun.bizarre = true;
      }
      acctSave(acc);
    }
    var sandboxUnlockedThisRun=!sandboxRun && preL < SANDBOX_UNLOCK_LEVEL && acc.level >= SANDBOX_UNLOCK_LEVEL;
    var sandboxUnlockBannerShown=false;
    function showSandboxUnlockBanner(level, tokenRef){
      if(!sandboxUnlockedThisRun || sandboxUnlockBannerShown || level !== SANDBOX_UNLOCK_LEVEL) return;
      sandboxUnlockBannerShown=true;
      showResultUnlockBanner('gorSandboxUnlockBanner');
      _gorTrackTimeout(tokenRef, function(){ sndSandboxUnlocked(tokenRef); }, 700);
    }
    var reasons={gold:'o ouro foi roubado',player:'cowboy abatido',both:'ambos caíram'};
    function set(id,v){ var e=document.getElementById(id); if(e) e.textContent=v; }
    set('gorSubtitle',reasons[reason]||'fim de jogo');
    set('gorStatWaves','0'); set('gorStatScore','0'); set('gorStatExp','+0');
    set('gorExpLevelLabel','Nível '+preL); set('gorExpGainLabel','+'+fmtExpNum(expG)+' EXP'); set('gorCoinsText','+ 0 Ouro ganho');
    function setDisplay(el, value){ if(el) el.style.display=value; }
    var expSection=document.getElementById('gorExpSection');
    var coinsRow=document.querySelector('#gameOverResults .gor-coins-row');
    var expStat=document.getElementById('gorStatExp');
    var expStatBox=expStat && expStat.closest ? expStat.closest('.gor-stat-box') : (expStat ? expStat.parentElement : null);
    setDisplay(expSection, sandboxRun ? 'none' : '');
    setDisplay(coinsRow, sandboxRun ? 'none' : '');
    setDisplay(expStatBox, sandboxRun ? 'none' : '');
    var multEl=document.getElementById('gorDifficultyMultiplier');
    if(multEl){
      if(sandboxRun){
        multEl.textContent='Sandbox: sem EXP ou Ouro de conta';
        multEl.setAttribute('data-difficulty','sandbox');
        multEl.title='O modo Sandbox não concede recompensas de conta.';
      } else {
        multEl.textContent='Mult. de dificuldade ('+difficultyReward.label+'): '+fmtDifficultyMultiplier(difficultyReward.multiplier);
        multEl.setAttribute('data-difficulty', difficultyReward.key);
        multEl.title=baseCoinsG.toLocaleString('pt-BR')+' Ouro base × '+difficultyReward.multiplier.toLocaleString('pt-BR')+' = '+coinsG.toLocaleString('pt-BR')+' Ouro';
      }
    }
    var banner=document.getElementById('gorLevelUpBanner'); if(banner) banner.style.display='none';
    var bizarreBanner=document.getElementById('gorBizarreUnlockBanner'); if(bizarreBanner) bizarreBanner.style.display='none';
    var hardBanner=document.getElementById('gorHardUnlockBanner'); if(hardBanner) hardBanner.style.display='none';
    var sandboxBanner=document.getElementById('gorSandboxUnlockBanner'); if(sandboxBanner) sandboxBanner.style.display='none';
    var commonBoxBanner=document.getElementById('gorCommonBoxBanner');
    if(commonBoxBanner){ commonBoxBanner.style.display='none'; commonBoxBanner.textContent='RECEBEU '+boxRewardsThisRun.common+' '+(boxRewardsThisRun.common===1?'CAIXA COMUM':'CAIXAS COMUNS'); }
    var specialBoxBanner=document.getElementById('gorSpecialBoxBanner');
    if(specialBoxBanner){ specialBoxBanner.style.display='none'; specialBoxBanner.textContent='RECEBEU '+boxRewardsThisRun.special+' '+(boxRewardsThisRun.special===1?'CAIXA ESPECIAL':'CAIXAS ESPECIAIS'); }
    if(difficultyUnlocksThisRun.bizarre){
      showResultUnlockBanner('gorBizarreUnlockBanner');
      _gorTrackTimeout(token, function(){ sndBizarreUnlocked(token); }, 360);
    }
    if(difficultyUnlocksThisRun.hard){
      showResultUnlockBanner('gorHardUnlockBanner');
      _gorTrackTimeout(token, function(){ sndHardUnlocked(token); }, difficultyUnlocksThisRun.bizarre ? 820 : 360);
    }
    var n0=expNeeded(preL), p0=(preE/n0*100).toFixed(1);
    var fill0=document.getElementById('gorExpBarFill'); if(fill0){ fill0.style.transition='none'; fill0.style.width=p0+'%'; }
    set('gorExpBarLabel',fmtExpNum(preE)+' / '+fmtExpNum(n0));
    var panel=document.getElementById('gameOverResults'); if(panel) {
      panel.classList.add('gor-visible');
      try{
        if (_gorOnlineResultContext){
          panel.setAttribute('data-online-result','1');
          panel.setAttribute('data-online-role', _gorOnlineResultContext.role || 'client');
        } else {
          panel.removeAttribute('data-online-result');
          panel.removeAttribute('data-online-role');
        }
      }catch(_){}
    }
    try{ document.body.setAttribute('data-results-open','1'); }catch(_){ }
    try{
      ['shopBtn','menuBackBtn','pauseBtn','ingameOptBtn','p1ShopBtn','p2ShopBtn'].forEach(function(id){
        var b=document.getElementById(id);
        if(b){ b.disabled=true; try{b.setAttribute('aria-disabled','true');}catch(_){ }
          try{ b.style.pointerEvents='none'; }catch(_){ }
          b.style.opacity='0.35'; b.style.filter='grayscale(1)';
        }
      });
    }catch(_){ }

    // A recompensa já foi salva acima; as animações não devem bloquear decisões do jogador.
    gorSetLocked(false);
    _gorTrackTimeout(token, function(){
      animateResultsPrelude(waves, score, expG, preL, token).then(function(){
        if(token!==_gorAnimToken) return;
        if(sandboxRun){
          gorSetLocked(false);
          _gorUpdateChanceBtn();
          return;
        }
        if(boxRewardsThisRun.common > 0){
          _gorTrackTimeout(token, function(){ showResultUnlockBanner('gorCommonBoxBanner'); sndCommonBox(token); }, 260);
        }
        if(boxRewardsThisRun.special > 0){
          _gorTrackTimeout(token, function(){ showResultUnlockBanner('gorSpecialBoxBanner'); sndSpecialBox(token); }, boxRewardsThisRun.common > 0 ? 760 : 260);
        }
        try{ animateBar(preL,preE,expG,coinsG, token, showSandboxUnlockBanner); }
        catch(_){ gorSetLocked(false); _gorUpdateChanceBtn(); }
      }).catch(function(){
        if(token===_gorAnimToken){ gorSetLocked(false); _gorUpdateChanceBtn(); }
      });
    }, 220);
  }

