        ctx2.beginPath(); ctx2.moveTo(px+15,py+19); ctx2.lineTo(px+15+Math.cos(hAngle-Math.PI/2)*4,py+19+Math.sin(hAngle-Math.PI/2)*4); ctx2.stroke();
