  // ── Botões ───────────────────────────────────────────────────────

  function _gorDoRestart(){
    if(_gorLocked) return;
    try{
      var _api0 = window.__defendaApi;
      var _st0 = _api0 && _api0.getState ? _api0.getState() : null;
      if(_st0 && _st0.onlineCoop && _st0.onlineRole !== 'host') return;
    }catch(_){}
    _gorCancelPendingAnims();
    gorSetLocked(false);
    _gorChanceIdx = 0;
    var _p=document.getElementById('gameOverResults'); if(_p) _p.classList.remove('gor-visible');

    try{ document.body.removeAttribute('data-results-open'); }catch(_){ }
    try{
      ['shopBtn','menuBackBtn','pauseBtn','ingameOptBtn','p1ShopBtn','p2ShopBtn'].forEach(function(id){
        var b=document.getElementById(id); if(!b) return;
        b.disabled=false; try{b.setAttribute('aria-disabled','false');}catch(_){ }
        try{ b.style.pointerEvents=''; }catch(_){ }
        b.style.opacity=''; b.style.filter=''; b.style.cursor='';
      });
    }catch(_){ }

    try{
      var api = window.__defendaApi;
      if(api && api.getState){
        var st = api.getState();
        if(st && st.onlineCoop){
          if(st.onlineRole !== 'host') return;
          if(window.__onlineCoop && window.__onlineCoop.restartGame) window.__onlineCoop.restartGame();
          return;
        }
        if(st && st.coop && api.resetGameCoop) api.resetGameCoop();
        else if(api.resetGame) api.resetGame();

        st = api.getState && api.getState();
        if(st){
          st.running=true; st.inMenu=false; st.pausedManual=false; st.pausedShop=false;
        }
        if(api.musicStop) api.musicStop();
        if(api.musicStart) api.musicStart();
      }
    }catch(_e){}
  }
  function _gorDoMenu(){
    if(_gorLocked) return;
    try{
      if (forceOnlineResultMenuConfirm()){
        return;
      }
    }catch(_){}
    _gorCancelPendingAnims();
    gorSetLocked(false);
    _gorChanceIdx = 0;
    var _p=document.getElementById('gameOverResults'); if(_p) _p.classList.remove('gor-visible');

    try{
      var body=document.body;
      if(body){
        body.removeAttribute('data-results-open');
        body.removeAttribute('data-shop-open');
        body.removeAttribute('data-esc-menu-open');
        body.removeAttribute('data-options-open');
        body.removeAttribute('data-confirm-open');
      }
    }catch(_){ }
    try{ syncInGameModalMusicDuck(); }catch(_){ }
    try{
      ['shopBtn','menuBackBtn','pauseBtn','ingameOptBtn','p1ShopBtn','p2ShopBtn'].forEach(function(id){
        var b=document.getElementById(id); if(!b) return;
        b.disabled=false; try{b.setAttribute('aria-disabled','false');}catch(_){ }
        try{ b.style.pointerEvents=''; }catch(_){ }
        try{ b.style.opacity=''; b.style.filter=''; b.style.cursor=''; }catch(_){ }
      });
    }catch(_){ }
    try{ if(window.__hudUnlockButtonsIfNoModal) window.__hudUnlockButtonsIfNoModal(); }catch(_){ }

    try{
      var api = window.__defendaApi;
      if(api && api.getState){
        if(api.resetGame) api.resetGame();
        var st = api.getState && api.getState();
        if(st){
          st.running=false; st.inMenu=true; st.pausedManual=false; st.coop=false; try{ delete st.player2; }catch(_){ }
        }
        try{ if (window.releaseCoopInputModeLock) window.releaseCoopInputModeLock(); }catch(_){ }
        if(api.musicStop) api.musicStop();
        if(api.showMenu) api.showMenu();
      }
    }catch(_e){}
  }

  // ─── Segunda Chance ─────────────────────────────────────────────
  // custo por uso dentro da mesma partida: 100 → 200 → 400 → 800 → 1000 (máx)
  var _gorChanceCosts = [100, 200, 400, 800, 1000];
  var _gorChanceIdx   = 0; // índice atual (aumenta a cada uso na partida)

  function _gorUpdateChanceBtn(){
    var btn  = document.getElementById('gorSecondChanceBtn');
    var span = document.getElementById('gorChanceCost');
    if (!btn) return;
    var cost = _gorChanceCosts[Math.min(_gorChanceIdx, _gorChanceCosts.length - 1)];
    var st = window.__defendaApi && window.__defendaApi.getState ? window.__defendaApi.getState() : state;
    var sandboxRun = !!(st && st.sandbox && st.sandbox.enabled);
    if (sandboxRun) cost = 0;
    if (span) span.textContent = cost;
    var acc = acctLoad();
    var canAfford = sandboxRun || acc.coins >= cost;
    // Só mexe no disabled por saldo — o lock de animação é responsabilidade do gorSetLocked
    btn.disabled = !canAfford;
    btn.style.opacity = canAfford ? '1' : '0.38';
    btn.style.filter  = canAfford ? '' : 'grayscale(1)';
    btn.style.cursor  = canAfford ? 'pointer' : 'not-allowed';
    try{ btn.removeAttribute('title'); }catch(_){} 
  }

  function _gorPlayEllipseScreenFlash(color){
    try{
      if (window.__defendaPlayEllipseScreenFlash){
        window.__defendaPlayEllipseScreenFlash(color);
        return;
      }
      var flash = document.getElementById('gorChanceFlash');
      if (!flash) return;
      var palettes = {
        yellow: ['rgba(255,220,60,0.92)', 'rgba(243,180,20,0.6)'],
        green: ['rgba(80,255,135,0.86)', 'rgba(30,190,80,0.56)'],
        red: ['rgba(255,70,70,0.86)', 'rgba(190,20,20,0.56)']
      };
      var colors = palettes[color] || palettes.yellow;
      flash.style.background = 'radial-gradient(ellipse at center, ' + colors[0] + ' 0%, ' + colors[1] + ' 40%, rgba(0,0,0,0) 75%)';
      flash.style.display = 'block';
      flash.style.animation = 'none';
      void flash.offsetWidth;
      flash.style.animation = 'gorFlashAnim 0.55s ease-out forwards';
      setTimeout(function(){ try{ flash.style.display = 'none'; }catch(_){} }, 600);
    }catch(_){}
  }

  function closeResultsPanelForContinue(){
    try{ if (typeof _gorCancelPendingAnims === 'function') _gorCancelPendingAnims(); }catch(_){}
    try{ if (typeof gorSetLocked === 'function') gorSetLocked(false); }catch(_){}
    var panel = document.getElementById('gameOverResults');
    if (panel){
      panel.classList.remove('gor-visible');
      try{ panel.removeAttribute('data-online-result'); panel.removeAttribute('data-online-role'); }catch(_){}
    }
    _gorOnlineResultContext=null;
    try{ window.__gorOnlineResultContext=null; }catch(_){}
    try{ document.body.removeAttribute('data-results-open'); }catch(_){}
    try{
      ['shopBtn','menuBackBtn','pauseBtn','ingameOptBtn','p1ShopBtn','p2ShopBtn'].forEach(function(id){
        var b=document.getElementById(id); if(!b) return;
        b.disabled=false;
        try{b.setAttribute('aria-disabled','false');}catch(_){}
        try{b.style.pointerEvents='';}catch(_){}
        b.style.opacity=''; b.style.filter=''; b.style.cursor='';
      });
    }catch(_){}
  }

  function playContinueLocalFeedback(){
    try{
      var bip = window._gameBeep || (window._G && window._G.beep);
      if (bip){
        bip(440, 0.06, 'triangle', 0.07);
        setTimeout(function(){ bip(554, 0.07, 'triangle', 0.08); }, 80);
        setTimeout(function(){ bip(659, 0.09, 'triangle', 0.09); }, 170);
        setTimeout(function(){ bip(880, 0.14, 'triangle', 0.12); }, 270);
        setTimeout(function(){ bip(1100,0.18, 'triangle', 0.14); }, 390);
        setTimeout(function(){ bip(1320,0.22, 'sine',     0.18); }, 530);
      }
    }catch(_){}
    _gorPlayEllipseScreenFlash('yellow');
    setTimeout(function(){
      try{
        var st = window.__defendaApi && window.__defendaApi.getState && window.__defendaApi.getState();
        if (st && st.fx && st.gold){
          var cx = st.gold.x * 32 + 16, cy = st.gold.y * 32 + 16;
          for (var i = 0; i < 40; i++){
            var ang = Math.random() * Math.PI * 2;
            var spd = 80 + Math.random() * 120;
            var life = 0.5 + Math.random() * 0.4;
            var cols = ['#f3d23b','#ffe066','#ffd700','#ffec80'];
            st.fx.push({
              x: cx + (Math.random()-0.5)*20,
              y: cy + (Math.random()-0.5)*20,
              vx: Math.cos(ang)*spd, vy: Math.sin(ang)*spd - 40,
              life: life, max: life,
              color: cols[Math.floor(Math.random()*cols.length)],
              size: 2.5 + Math.random()*2, grav: 120
            });
          }
        }
      }catch(_){ }
    }, 80);
  }

  function resumeGameplayMusicAfterContinue(){
    try{
      var api = window.__defendaApi;
      if (api && api.resumeGameplayMusic) api.resumeGameplayMusic();
      else if (api && api.musicStart) api.musicStart();
    }catch(_){}
  }

  const CONTINUE_INVULNERABILITY_SECONDS = 3.0;

  function handleOnlineContinueEvent(ev){
    ev = ev || {};
    const seq = Math.max(0, Number(ev.continueSeq) || 0);
    var api = window.__defendaApi;
    var st = api && api.getState ? api.getState() : null;
    if (seq){
      if (st && seq <= (Number(st._onlineContinueSeqApplied) || 0)) return;
      if (st) st._onlineContinueSeqApplied = seq;
    }
    closeResultsPanelForContinue();
    playContinueLocalFeedback();
    try{
      if (st){
        st.running = true;
        st.gameOverReason = null;
        st.inMenu = false;
        st.pausedManual = false;
        st.pausedShop = false;
        st.goldInvulT = CONTINUE_INVULNERABILITY_SECONDS;
        st.playerInvulT = CONTINUE_INVULNERABILITY_SECONDS;
        st.accountCoinsRewardWaveBase = Math.max(0, (st.wave || 1) - 1);
        st.accountCoinsRewardScoreBase = st.score || 0;
        st.accountCoinsRewardOnlineScoreBaseById = {};
        st.accountCoinsRewardOnlineScoreBaseBySlot = {};
        if (st.player) st.player.invulT = CONTINUE_INVULNERABILITY_SECONDS;
        if (st.player2) st.player2.invulT = CONTINUE_INVULNERABILITY_SECONDS;
        if (Array.isArray(st.onlinePlayers)){
          st.onlinePlayers.forEach(function(op){
            if (!op) return;
            if (op.actor) op.actor.invulT = CONTINUE_INVULNERABILITY_SECONDS;
            var scoreBase = Math.max(0, Number(op.totalScore || op.score || 0) || 0);
            if (op.id) st.accountCoinsRewardOnlineScoreBaseById[op.id] = scoreBase;
            if (op.slot != null) st.accountCoinsRewardOnlineScoreBaseBySlot[String(op.slot)] = scoreBase;
          });
        }
        try{ delete st._gorResultsShown; }catch(_){ st._gorResultsShown = false; }
      }
      try{
        const tm = window._G && window._G.toastMsg;
        if (tm) tm('💛 Continuar! +100 vida ao ouro e ao cowboy');
      }catch(_){}
      resumeGameplayMusicAfterContinue();
    }catch(_){}
  }
  window.__defendaHandleOnlineContinueEvent = handleOnlineContinueEvent;

  function _gorDoSecondChance(){
    var st0 = window.__defendaApi && window.__defendaApi.getState ? window.__defendaApi.getState() : state;
    var isOnlineHostContinue = !!(st0 && st0.onlineCoop && st0.onlineRole === 'host');
    if (_gorLocked && !isOnlineHostContinue) return;
    _gorCancelPendingAnims();
    var cost = _gorChanceCosts[Math.min(_gorChanceIdx, _gorChanceCosts.length - 1)];
    var acc  = acctLoad();
    var sandboxRun = !!(st0 && st0.sandbox && st0.sandbox.enabled);
    if (sandboxRun) cost = 0;
    if (acc.coins < cost) return;

    // Deduz ouro da conta
    if (cost > 0){
      acc.coins -= cost;
      acctSave(acc);
    }
    // Avança custo para a próxima vez (até o máximo)
    if (_gorChanceIdx < _gorChanceCosts.length - 1) _gorChanceIdx++;

    // ── Efeito sonoro grandioso ──
    try{
      var bip = window._gameBeep || (window._G && window._G.beep);
      if (bip){
        bip(440, 0.06, 'triangle', 0.07);
        setTimeout(function(){ bip(554, 0.07, 'triangle', 0.08); }, 80);
        setTimeout(function(){ bip(659, 0.09, 'triangle', 0.09); }, 170);
        setTimeout(function(){ bip(880, 0.14, 'triangle', 0.12); }, 270);
        setTimeout(function(){ bip(1100,0.18, 'triangle', 0.14); }, 390);
        setTimeout(function(){ bip(1320,0.22, 'sine',     0.18); }, 530);
      }
    }catch(_){}

    // ── Flash dourado na tela ──
    _gorPlayEllipseScreenFlash('yellow');

    // ── Partículas douradas no canvas ──
    setTimeout(function(){
      try{
        var st = window.__defendaApi && window.__defendaApi.getState && window.__defendaApi.getState();
        if (st && st.fx && st.gold){
          var cx = st.gold.x * 32 + 16, cy = st.gold.y * 32 + 16;
          for (var i = 0; i < 40; i++){
            var ang = Math.random() * Math.PI * 2;
            var spd = 80 + Math.random() * 120;
            var life = 0.5 + Math.random() * 0.4;
            var cols = ['#f3d23b','#ffe066','#ffd700','#ffec80'];
            st.fx.push({
              x: cx + (Math.random()-0.5)*20,
              y: cy + (Math.random()-0.5)*20,
              vx: Math.cos(ang)*spd, vy: Math.sin(ang)*spd - 40,
              life: life, max: life,
              color: cols[Math.floor(Math.random()*cols.length)],
              size: 2.5 + Math.random()*2, grav: 120
            });
          }
        }
      }catch(_){ }
    }, 80);

    // ── Fechar tela de resultados e retomar jogo ──
    closeResultsPanelForContinue();

    // ── Restaurar 100 de vida no ouro e retomar ──
    try{
      var api = window.__defendaApi;
      if (api && api.getState){
        var st2 = api.getState();
        if (st2){
          // Restaura HP do ouro
          st2.gold.hp = Math.min(st2.gold.max, Math.max(st2.gold.hp || 0, 0) + 100);
          if (st2.gold.hp <= 0) st2.gold.hp = 100;
          // Restaura HP do jogador e dá invulnerabilidade de 3s
          if (st2.onlineCoop && Array.isArray(st2.onlinePlayers)){
            st2.onlinePlayers.forEach(function(op){
              if (!op || !op.actor) return;
              var maxHp = op.actor.max || op.actor.maxHp || 100;
              op.actor.hp = Math.min(maxHp, Math.max(op.actor.hp || 0, 0) + 100);
              if (op.actor.hp <= 0) op.actor.hp = Math.min(maxHp, 100);
              op.actor.invulT = CONTINUE_INVULNERABILITY_SECONDS;
              op.reviveProgress = 0;
              op.actor.inShop = false;
            });
            try{ syncOnlineScoreAliases(); }catch(_){}
          } else if (st2.player){
            st2.player.hp = Math.min(st2.player.max || 100, (st2.player.hp || 0) + 100);
            if (st2.player.hp <= 0) st2.player.hp = 100;
            st2.player.invulT = CONTINUE_INVULNERABILITY_SECONDS;
            if (st2.player2){
              st2.player2.hp = Math.min(st2.player2.max || 100, (st2.player2.hp || 0) + 100);
              if (st2.player2.hp <= 0) st2.player2.hp = 100;
              st2.player2.invulT = CONTINUE_INVULNERABILITY_SECONDS;
            }
          }
          st2.playerInvulT = CONTINUE_INVULNERABILITY_SECONDS;
          st2.dead1 = false;       // limpa estado de morto do singleplayer
          try{ delete st2._gorResultsShown; }catch(_){ st2._gorResultsShown = false; }
          // A partir daqui, ouro de conta só conta o progresso após este continuar
          st2.accountCoinsRewardWaveBase = Math.max(0, (st2.wave || 1) - 1);
          st2.accountCoinsRewardScoreBase = st2.score || 0;
          st2.accountCoinsRewardOnlineScoreBaseById = {};
          st2.accountCoinsRewardOnlineScoreBaseBySlot = {};
          if (st2.onlineCoop && Array.isArray(st2.onlinePlayers)){
            st2.onlinePlayers.forEach(function(op){
              if (!op) return;
              var scoreBase = Math.max(0, Number(op.totalScore || op.score || 0) || 0);
              if (op.id) st2.accountCoinsRewardOnlineScoreBaseById[op.id] = scoreBase;
              if (op.slot != null) st2.accountCoinsRewardOnlineScoreBaseBySlot[String(op.slot)] = scoreBase;
            });
          }
          // Limpa estado de game over
          st2.gameOverReason = null;
          st2.gameOverFade   = 0;
          // Reativa o jogo
          st2.running      = true;
          st2.inMenu       = false;
          st2.pausedManual = false;
          st2.pausedShop   = false;
          st2.goldInvulT = CONTINUE_INVULNERABILITY_SECONDS;
          if (st2.onlineCoop && st2.onlineRole === 'host'){
            st2.onlineContinueSeq = (st2.onlineContinueSeq || 0) + 1;
            try{ if (window.__onlineCoop && window.__onlineCoop.continueGame) window.__onlineCoop.continueGame(); }catch(_){}
            try{ forceOnlineMetaSnapshotSoon(); }catch(_){}
          }
          // Toast
          try{
            var tm = window._G && window._G.toastMsg;
            if (tm) tm('💛 Continuar! +100 vida ao ouro e ao cowboy');
          }catch(_){ }
          // Popup dourado flutuante no ouro
          try{
            var gx2 = st2.gold.x * 32 + 16, gy2 = st2.gold.y * 32 - 10;
            if (st2.multiPopups){
              st2.multiPopups.push({ text:'+100 ❤', x:gx2, y:gy2, vy:-38, life:1.1, max:1.1, color:'#f3d23b' });
            }
          }catch(_){ }
        }
        resumeGameplayMusicAfterContinue();
      }
    }catch(_e){}

    // Atualiza HUD de ouro (label de moedas no perfil)
    try{
      var e = document.getElementById('profCoinsLabel');
      if(e){ var a2=acctLoad(); e.textContent=a2.coins.toLocaleString('pt-BR')+' Ouro'; }
    }catch(_){ }
  }

  var btnR = document.getElementById('gorContinueBtn');
  if(btnR) btnR.onclick = _gorDoRestart;

